BEGIN;

-- Add tradition column if it doesn't exist
ALTER TABLE doctrine_covenants_verses ADD COLUMN IF NOT EXISTS tradition VARCHAR(10) DEFAULT 'shared';
ALTER TABLE doctrine_covenants_verses ADD COLUMN IF NOT EXISTS prophet_received VARCHAR(100);
ALTER TABLE doctrine_covenants_verses ADD COLUMN IF NOT EXISTS date_received DATE;
ALTER TABLE doctrine_covenants_verses ADD COLUMN IF NOT EXISTS conference_date DATE;

-- Insert CoC-specific sections
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (114, 1, 'October 7, 1861-This is the first revelation to the church through Joseph Smith III. It was initially published as an appendix to the first general epistle sent from the Quorum of Twelve "to all the Saints scattered abroad." The Twelve are to work with the Bishop in executing the law of tithing D&C 114:1a In order to place the church in a position to carry on the promulgation of the gospel and as a means of fulfilling the law, the Twelve will take measures in connection with the Bishop to execute the law of tithing; D&C 114:1b and let them before God see to it that the temporal means so obtained is truly used for the purposes of the church-and not as a weapon of power in the hands of one man for the oppression of others or for the purposes of self-aggrandizement by anyone, be he whosoever he may be. D&C 114:2 As I live, saith the Lord, in the manner ye execute this matter, so shall ye be judged in the day of judgment.', 'coc', 'Joseph Smith III', '1860-04-16', '1860-04-06');
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (115, 1, 'March, 1863-Revelation given through Joseph Smith III and addressed to the elders of the church. William Marks is called to the First Presidency-Elders are to travel two by two to preach the gospel D&C 115:1a Hearken unto me, O ye elders of my church. Lo, I have seen your efforts in my cause, and they are pleasing unto me. D&C 115:1b I declare unto you, It is my will that you ordain and set apart my servant William Marks to be a counselor to my servant Joseph, even the President of my church, that the First Presidency of my church may be more perfectly filled. D&C 115:1c And, moreover, it is expedient in me that my elders, in going to declare my gospel to the nations, shall observe the pattern which I have given. D&C 115:1d Two by two let them be sent, that they may be a help and a support to each other in their ministry. D&C 115:1e Press onward, ye elders and people of my church, even my little flock; and, as I have spoken to you in times past, so will I speak again to you as my friends, inasmuch as you speak in my name; and lo, I am Alpha and Omega and will be with you unto the end. Amen.', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (116, 1, 'May 4, 1865-Kendall County, Illinois. Following the United States Civil War, a council of the First Presidency and Quorum of Twelve met at the home of Bishop Israel L. Rogers to consider a number of issues, including "the ordination of men of the Negro race." Joseph Smith III received this revelation in response to the fasting and prayer of the council to receive the Lord''s will. Men of every race may be ordained to the priesthood-Admonitions to the priesthood D&C 116:1a Hearken, ye elders of my church. I am he who hath called you friends. Concerning the matter you have asked of me, D&C 116:1b Lo, it is my will that my gospel shall be preached to all nations in every land and that men of every tongue shall minister before me; D&C 116:1c therefore, it is expedient in me that you ordain priests unto me of every race who receive the teachings of my law and become heirs according to the promise. D&C 116:2a Be ye very careful, for many elders have been ordained unto me and are come under my condemnation, by reason of neglecting to lift up their voices in my cause; and for such there is tribulation and anguish; D&C 116:2b haply they themselves may be saved (if doing no evil) though their glory, which is given for their works, be withheld or, in other words, their works are burned, not being profitable unto me. D&C 116:3a Loosen ye one another''s hands, and uphold one another, that ye who are of the Quorum of Twelve may all labor in the vineyard, for upon you rests much responsibility; D&C 116:3b and if ye labor diligently, the time is soon when others shall be added to your number till the quorum be full, even twelve. D&C 116:4a Be not hasty in ordaining men of the Negro race to offices in my church; for verily, I say unto you, D&C 116:4b All are not acceptable unto me as servants; nevertheless, I will that all may be saved, but every man in his own order; and there are some who are chosen instruments to be ministers to their own race. Be ye content; I, the Lord, have spoken it.', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (117, 1, 'March 3, 1873-Plano, Illinois. Joseph Smith III received this revelation "in answer to long and continued and earnest prayer to God upon the condition of the quorums of the church." Joseph''s only counselor in the First Presidency, William Marks, had died the previous year, and the death of Apostle Samuel Powers in February had left the Quorum of Twelve with only five members. Following this revelation, the First Presidency was filled for the first time since the church was reorganized in 1860. W. W. Blair and David H. Smith are called to the Presidency-Several are called to the Quorum of Twelve-The Bishop is to choose counselors and bishop''s agents-Let contentions cease D&C 117:1 Hearken to the voice of the Spirit, O ye elders of my church. The prayers of my people have prevailed with me. D&C 117:2 Behold, it is wisdom in me and expedient in my church that the chief quorums should be more nearly filled and their organization more nearly completed. Thus saith the Spirit: D&C 117:3a Let my servants William W. Blair and David H. Smith be chosen and ordained to be counselors to my servant, the presiding elder of my church. D&C 117:3b Let them be set apart to this office by the laying on of hands by my servants, whose duty it is to ordain and set in order the officers of my church; D&C 117:3c and let my servants, the president of the high priests'' quorum and the president of the lesser priesthood, also lay their hands upon these, their brethren, who are to be counselors; but let my servants of the Twelve be the spokesmen. D&C 117:4a Let my servants William H. Kelley, Thomas W. Smith, James Caffall, John H. Lake, Alexander H. Smith, Zenas H. Gurley, and Joseph R. Lambert be chosen as especial witnesses, even of the Quorum of Twelve, for they are called thereunto that they may take this ministry upon them. D&C 117:4b Let them be ordained and set apart to this office by the laying on of the hands of my servants Joseph Smith, Jason W. Briggs, and William W. Blair. D&C 117:5 Verily, I say unto you, If these, my servants, will henceforth magnify their calling in honor before me, they shall become men of power and excellent wisdom in the assemblies of my people. D&C 117:6 Let the names of my servants Daniel B. Rasey and Reuben Newkirk be taken from the record of the Quorum of the Twelve and placed with the records of the names of the elders; and let them labor as elders, and their labors will be accepted by me. D&C 117:7a It is my will that my servants Jason W. Briggs, Josiah Ells, and Edmund C. Briggs remain and stand in their lot as especial witnesses before me. D&C 117:7b Let them diligently labor in their ministry, encouraging and directing their brethren in their labors. D&C 117:7c It is expedient for the good of my cause that my servant Jason take the active oversight of this quorum. D&C 117:8a Let my servants Archibald M. Wilsey, William D. Morton, and George Rarick be ordained high priests; D&C 117:8b and let my servants E. C. Brand, Charles W. Wandell, and Duncan Campbell be appointed as special witnesses of the Seventy in their places; D&C 117:8c and let my servants Joseph Lakeman, Glaud Rodger, John T. Davies, and John S. Patterson be also appointed as witnesses of the Seventy before me. D&C 117:9a Until such time as the Quorum of the Twelve shall be filled, the decision of that quorum, a unanimous decision, shall be accounted final, as if such quorum were filled, according to my law as given in the Book of Doctrine and Covenants. D&C 117:9b And until such time as the Quorum of the Seventy shall be filled, their decision, if unanimous and agreeing with that of the Quorum of the Twelve, shall be considered the same as if the quorum were filled. D&C 117:10a It is expedient that the Bishop of my church shall choose two counselors and that they be ordained to their office as my law directs, that there may be henceforth no caviling among my people. D&C 117:10b The Bishop of my church may also choose and appoint Bishop''s agents until it shall be wisdom in me to ordain other bishops in the districts and large branches of my church. D&C 117:11a It is not expedient in me that there shall be any stakes appointed until I command my people. When it shall be necessary, I will command that they be established. D&C 117:11b Let my commandments to gather into the regions round about and the counsel of the elders of my church guide in this matter until it shall be otherwise given of me. D&C 117:12 Behold, if my servants and my handmaidens of the different organizations for good among my people shall continue in righteousness, they shall be blessed, even as they bless others of the household of faith. D&C 117:13 Let contentions and quarrelings among you cease. Sustain each other in peace; and ye shall be blessed with my Spirit, in comforting and strengthening you for my work. D&C 117:14 It is not expedient that I command you further at this time; but be ye diligent, wise, and faithful, doing all things with an eye single for the glory of your God and for the good of his people. Thus saith the Lord. Amen.', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (118, 1, 'September 28, 1882-Lamoni, Iowa. Revelation through Joseph Smith III in response to the prayers of the General Conference concerning two matters: the filling of the leading quorums and the administration of the work in Chicago. Need for further organization and unity-Heed the counsel of the traveling ministry D&C 118:1a In asking of me, ye did well. I will hasten my work in its time. D&C 118:1b Ye cannot now prosecute missions in many foreign lands, nor is it expedient that the elders of the first quorums be sent out of the land of America until the work of the reorganization of my church be more fully established and a greater unity of understanding between them be obtained. D&C 118:1c Nor is it expedient now to further fill up the quorums, except it be the elders, priests, teachers, and deacons, which ye may do, as ye deem wise, by the direction of conference. D&C 118:2 Continue the mission in Chicago until the April conference when, if it be found expedient, it may be left in the charge of the authorities of the Northern Illinois District. D&C 118:3 It is my will that ye more fully honor and pay heed to the voice and counsel of the traveling ministry in spiritual things-which if ye do not, the office which they hold is not honored in my service, and the good they should do is made void. D&C 118:4a If they approve themselves as righteous ministers, they shall be blessed; if they be found transgressors or idle servants, ye shall not uphold them. D&C 118:4b But be not hasty in withdrawing your support from them, peradventure ye shall injure my work. D&C 118:4c Even now I am not well pleased with some, but space is granted for repentance and a renewal of diligence. Let no one deceive himself that he shall not account for his stewardship unto me. Joseph Smith By command of the Spirit', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (119, 1, 'April 11, 1887-Kirtland, Ohio. Revelation to the elders of the church through Joseph Smith III in response to a concern over vacancies in the Quorum of Twelve. Elders are to be of sober mind, studious, humble, sincere, and set a good example-Instructions concerning the sacrament, service of song, keeping the Sabbath, prosecuting the missionary work, and care of the mind and body To the Elders of the Church: Thus saith the Spirit: D&C 119:1a It is not yet expedient that the Quorum of the Twelve shall be filled; nevertheless, separate my servants James W. Gillen, Heman C. Smith, Joseph Luff, and Gomer T. Griffiths unto the office of apostle, that the quorum may be more perfectly prepared to act before me. D&C 119:1b I have still other men of my church who shall be designated in their time if they still continue faithful unto me and in the work whereunto they are now called. D&C 119:2a There is a great work to be done by mine elders; and that they may be fitted to do this work and the accomplishment thereof be not prevented, it is enjoined upon them that they shall not only be kind of heart and of a lowly spirit, that their wisdom may be the wisdom of the Lord and their strength the strength of the Spirit, D&C 119:2b but they shall lay aside lightness of speech and lightness of manner when standing to declare the word and shall study to approve their ministrations to the people by candor in speech and courtesy in demeanor, that as ministers of the gospel they may win souls unto Christ. D&C 119:3a The elders and men of the church should be of cheerful heart and countenance among themselves and in their intercourse with their neighbors and men of the world; yet they must be without blame in word and deed. D&C 119:3b It is, therefore, not seemly that they indulge in loud and boisterous speech or in the relating of coarse and vulgar stories or those in which the names of their God and their Redeemer are blasphemed. D&C 119:3c Men of God, who bear the vessels of the Lord, be ye clean in your bodies and in your clothing; let your garments be of a sober character and free from excess of ornamentation. D&C 119:3d Avoid the use of tobacco, and be not addicted to strong drink in any form, that your counsel to be temperate may be made effectual by your example. D&C 119:4a That the work of restoration-to which the people of my church are looking forward-may be hastened in its time, the elders must cease to be overcareful concerning the return of those who were once of the faith but were overcome in the dark and cloudy day, fearing, lest they should bring in hidden heresies to the overthrowing of the work; D&C 119:4b for verily, there are some who are chosen vessels to do good, who have been estranged by the hindering snares which are in the world and who will in due time return unto the Lord if they be not hindered by the men of the church. D&C 119:4c The Spirit says, Come. Let not the ministers for Christ prevent their coming. D&C 119:5a And the Spirit saith further: Contention is unseemly; therefore, cease to contend respecting the sacrament and the time of administering it; D&C 119:5b for whether it be upon the first Lord''s day of every month or upon the Lord''s day of every week, if it be administered by the officers of the church with sincerity of heart and in purity of purpose, and be partaken of in remembrance of Jesus Christ and in willingness to take upon them his name by them who partake, it is acceptable to God. D&C 119:5c To avoid confusion, let him who presides in the sacrament meeting and those who administer it cause that the emblems be duly prepared upon clean vessels for the bread and clean vessels for the wine or the water, as may be expedient; D&C 119:5d and the officer may break the bread before it is blessed and pour the wine before it is blessed; or he may, if he be so led, bless the bread before it be broken and the wine before it be poured; D&C 119:5e nevertheless, both bread and wine should be uncovered when presented for the blessing to be asked upon it. D&C 119:5f It is expedient that the bread and wine should be administered in the early part of the meeting, before weariness and confusion ensue. D&C 119:5g Let him that partaketh and him that refraineth cease to contend with his brother, that each may be benefited when he eateth at the table of the Lord. D&C 119:6a The service of song in the house of the Lord, with humility and unity of Spirit in them that sing and them that hear, is blessed and acceptable with God; but song with grievous sadness in them that sing and bitterness of spirit in them that hear is not pleasing to God. D&C 119:6b Therefore, in all the congregations of the people of God, let all strife and contention concerning song service cease; D&C 119:6c and that the worship in the house of the Lord may be complete and wholly acceptable, let them who shall be moved thereto by a desire and the gift to sing take upon them the burden and care of the service and use therein instruments of music of the reed and of the string, or instruments of brass in congregations that are large, and as wisdom and choice may direct. D&C 119:6d Let the young men and the maidens cultivate the gifts of music and of song; let not the middle-aged and the old forget the gladsomeness of their youth, and let them aid and assist so far as their cares will permit. And remember that Saints should be cheerful in their warfare, that they may be joyous in their triumph. D&C 119:6e Nevertheless, let the organ, and the stringed instrument, and the instrument of brass be silent when the Saints assemble for prayer and testimony, that the feelings of the tender and sad may not be intruded upon. D&C 119:6f To facilitate unity in the song service of the church, those to whom the work of providing a book of song has been intrusted may hasten their work in its time. D&C 119:7a And the Spirit saith further: Inasmuch as there has been much discussion in the past concerning the Sabbath of the Lord, the church is admonished that-until further revelation is received or the quorums of the church are assembled to decide concerning the law in the church articles and covenants- D&C 119:7b the Saints are to observe the first day of the week, commonly called the Lord''s day, as a day of rest, as a day of worship, as given in the covenants and commandments. D&C 119:7c And on this day they should refrain from unnecessary work; nevertheless, nothing should be permitted to go to waste on that day, nor should necessary work be neglected. D&C 119:7d Be not harsh in judgment but merciful in this, as in all other things. Be not hypocrites nor of those who make a man an offender for a word. D&C 119:8a Prosecute the missionary work in this land and abroad so far and so widely as you may. D&C 119:8b All are called according to the gifts of God unto them; and to the intent that all may labor together, let him that laboreth in the ministry and him that toileth in the affairs of the men of business and of work labor together with God for the accomplishment of the work intrusted to all. D&C 119:9a Be clean; be frugal; cease to complain of pain, and sickness, and distress of body; take sleep in the hours set apart by God for the rebuilding and strengthening of the body and mind; D&C 119:9b for even now there are some, even among the elders, who are suffering in mind and body, who have disregarded the advice of the Spirit to retire early and to rise early, that vigor of mind and body should be retained. D&C 119:9c Bear the burdens of body of which the Spirit of healing from the Lord in faith, or the use of that which wisdom directs, does not relieve or remove; and in cheerfulness do whatever may be permitted you to perform, that the blessing of peace may be upon all. Amen. Kirtland, Ohio, April 11, 1887', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (120, 1, 'April 8, 1890-Lamoni, Iowa. Revelation through Joseph Smith III addressed to the First Presidency and the Quorum of Twelve regarding differences of opinion concerning an "Epistle" issued by the Twelve, which discussed the duties of branch and district presidents. The General Conference also sought divine guidance on questions regarding the call and ordination of high priests. The organization of branches and districts-Roles of traveling and standing ministry-Ordination of high priests-Vacancies to be filled in the high council and the First Quorum of Seventy Unto my servants, the First Presidency and the traveling High Council of my Church, thus saith the Spirit: D&C 120:1a The epistle is to be left without approval or disapproval by the conference, as the judgment of the Quorum of the Twelve, until further experience shall have tested the matters therein stated. D&C 120:1b In the meantime, branches and their officers and districts and their officers are to be considered as provided for by my law to carry on the work of the ministry in caring for the membership of the church and to relieve the Twelve and Seventy from the vexation and anxiety of looking after local organizations when effected. D&C 120:1c When branches and districts are organized, they should be so organized by direction of the conferences, or by the personal presence and direction of the Twelve, or some member of that quorum who may be in charge, if practicable; D&C 120:1d or, if a branch, by the president of the district with the consent, knowledge, and direction of the missionary in charge, when circumstances prevent the missionary in charge being present. D&C 120:2a A branch may be presided over by a high priest, an elder, priest, teacher, or deacon chosen and sustained by the vote of the branch. D&C 120:2b Districts may be presided over by a high priest or an elder, who shall be received and sustained in his office by the vote of the district. D&C 120:2c If a branch or district be large, he who is chosen to preside should be a high priest, if there be one possessed of the spirit of wisdom to administer in the office of president; D&C 120:2d or if an elder be chosen who may by experience be found qualified to preside, as soon as practicable thereafter he should be ordained a high priest by the spirit of wisdom and revelation in the one ordaining and by direction of a high council or General Conference, as required in the law. D&C 120:3a There should be no conflict or jealousy of authority between the quorums of the church; all are necessary and equally honorable, each in its place. D&C 120:3b The Twelve and Seventy are traveling ministers and preachers of the gospel, to persuade men to obey the truth; D&C 120:3c the high priests and elders, holding the same priesthood, are the standing ministers of the church, having the watchcare of the membership and nurturing and sustaining them, under the direction and instruction of the Presidency and the Twelve. D&C 120:3d The Seventy, when traveling by the voice of the church or sent by the Twelve to minister the word where the Twelve cannot go, are in the powers of their ministration apostles-those sent-and in meetings where no organization exists should preside if no member of the Twelve or Presidency be present. D&C 120:4a In both branches and districts the presiding officers should be considered and respected in their offices; D&C 120:4b nevertheless, the traveling presiding councils of the church being made by the law, their calling, and the voice of the church the directing, regulating, and advising authorities of the church, and representing it abroad-should, when present in either district or branch, be regarded and considered as the leading representative authorities of the church and be respected as such, their counsel and advice be sought and respected when given; D&C 120:4c and in cases of conflict or extremity, their decision should be listened to and regarded, subject to the appeal and adjudication provided for in the law. D&C 120:5 He that heareth him that is sent, heareth the Lord who sent him-if he be called of God and be sent by the voice of the church. D&C 120:6 In these matters there is no conflict in the law. D&C 120:7a In matters of personal importance and conduct arising in branches or districts, the authorities of those branches and districts should be authorized and permitted to settle them- D&C 120:7b the traveling councils taking cognizance of those only in which the law and usages of the church are involved and the general interests of the church are concerned. D&C 120:7c Where cases of difficulty are of long standing, the council may require local authorities to adjust them; and in case of failure to do so, may regulate them as required by their office and duty-and this that the work and church may not be put to shame and the preaching of the word be hindered. D&C 120:8 That the traveling council of the Twelve may be better prepared to act as a quorum, my servant A. H. Smith may be chosen president of the Twelve and any one of the council be chosen to act as its secretary until the quorum be filled or other instruction be given. D&C 120:9a Those who were presented by the high priests for ordination to their number, if approved by the council of the high priests now present and the conference, may be ordained; D&C 120:9b and from their number there may be selected by a committee of conference-composed of one of the First Presidency, the president of the Twelve, and one other to be chosen by the Council of Twelve, the president of the high priests, and one other to be chosen by that council of their number- D&C 120:9c a sufficient number to fill the vacancies now existing in the high council, that the high council may be properly organized and prepared to hear matters of grave importance when presented to them. D&C 120:9d And this committee shall make these selections according to the spirit of wisdom and revelation that shall be given unto them, to provide that such council may be convened at any General Conference when emergency may demand, by reason of their residing at or near to places where conferences may be held. D&C 120:10a The presidents of Seventy are instructed to select from the several quorums of elders such as are qualified and in a condition to take upon them the office of Seventy, that they may be ordained unto the filling of the first quorum of Seventy. D&C 120:10b In making these selections, the presidents of Seventy should confer with the several quorums before so selecting and be guided by wisdom and the spirit of revelation, choosing none but men of good repute.', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (121, 1, 'April, 1885-Independence, Missouri. A series of instructions given through Joseph Smith III to address several questions being considered by the General Conference. Instructions concerning members of the leading quorums and the work in Chicago D&C 121:1a At the April session of conference of 1885, during the consideration of the sustaining of the officers of the church made the special order for the 11th, when David H. Smith, second counselor to the President, was presented, the question was asked whether any communication had been received in regard to it. D&C 121:1b The President of the church replied: The voice of the Spirit is that David H. Smith be released. He is in mine hand. D&C 121:2a When the Quorum of the Twelve were presented, the question was again asked: Has any information been received concerning said quorum? D&C 121:2b President Joseph Smith replied: The voice of the Spirit is that E. C. Briggs be sustained for the present. J. W. Briggs and Z. H. Gurley are in your hands, to approve or disapprove as wisdom may direct. Be merciful, for to him that is merciful shall mercy be shown. D&C 121:3 On the 14th of the month, the eighth day of the session, when the mission of Elder E. C. Briggs was being considered, the following instruction was presented as the will of the Lord concerning the Chicago mission, over which some trouble had occurred: D&C 121:4a It is my will that my servants shall contend no longer one with another in regard to the Chicago Branch. Let the branch be instructed to report to the conference of my Saints of the district where the branch is located, the Northern Illinois District. D&C 121:4b My servants, the elders, when passing to and from, should labor in the city when time and opportunity permit, that my people there may be strengthened and encouraged. D&C 121:4c And this should be agreeable to the elders in charge of the branch and the district, who should ever be willing to aid such ministration; and this should be without jealousy on either part. D&C 121:5a The following, also received in 1885, is added by direction of the conference of 1894: D&C 121:5b My servants of the Seventy may select from their number, seven-of which number those now being of the seven presidents of Seventy shall be a part-who shall form the presidency of seven presidents of Seventy as provided in my law. D&C 121:6a The foregoing was accepted as proper instruction, and the conference acted upon it as such; but the word received was not presented to the quorums nor acted upon by them as is the usual custom of the church in regard to revelations received for the guidance of the church. D&C 121:6b It is given here as having been acquiesced in by all, in answer to prayer, and decisive upon the matters referred to.', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (122, 1, 'April 15, 1894-Lamoni, Iowa. Revelation to the church through Joseph Smith III in response to a resolution of the Twelve, which requested President Smith to "ask for further revelation in explanation of the authority and duties of the several quorums and their members, also for instruction providing for filling the vacancies in the leading quorums, including a designation of the Patriarch, if it shall be the pleasure of our heavenly Father to so enlighten us." Duties of the Presidency, Twelve, Seventy, Bishopric, and the standing ministry-Quorums in order of their authority-Priesthood are to labor together in harmony I was, on the fifteenth day of the fourth month, of the year 1894, in fasting and prayer before the Lord; and, being commanded of the Spirit, I arose from my praying and wrote, Thus saith the Spirit unto the Elders and the Church: D&C 122:1a My servants have been harsh one with another; and some have not been sufficiently willing to hear those whose duty it is to teach the revelations which my church has already received. D&C 122:1b Until my people shall hear and heed those who are set in the church to teach the revelations, there will be misunderstanding and confusion among the members. D&C 122:2a The burden of the care of the church is laid on him who is called to preside over the high priesthood of the church and on those who are called to be his counselors; D&C 122:2b and they shall teach according to the spirit of wisdom and understanding and as they shall be directed by revelation from time to time. D&C 122:3a It is the duty of the Twelve to preach the gospel and administer in the ordinances thereof as is directed in the Scriptures which ye have received. D&C 122:3b They are called and set apart to this duty and are to travel and preach under the direction and counsel of the Presidency. D&C 122:4a It is not yet expedient in me that the Quorum of the Presidency and the Quorum of the Twelve Apostles shall be filled, for reasons which will be seen and known unto you in due time. D&C 122:4b My servant David H. Smith is yet in my hand, and I will do my will in the time for its accomplishment. Be not troubled or fearful in this matter, for it shall be well for my work in the end. D&C 122:5a When I said unto mine apostles, "The Twelve will take measures in connection with the Bishop to execute the law of tithing; and let them before God see to it that the temporal means so obtained is truly used for the purposes of the church-and not as a weapon of power in the hands of one man for the oppression of others or for the purposes of self-aggrandizement by anyone, be he whosoever he may be," D&C 122:5b the one whom I had called to preside over the church had not yet approved himself unto the scattered flock. And I gave this command unto the quorum next in authority in spiritual things, that the scattered ones and those who had been made to suffer might have assurance that I would not suffer that he whom I had called should betray the confidence of the faithful nor squander the moneys of the treasury for the purposes of self- D&C 122:5c and for the reason that the law of tithing was but little understood and would not be observed unless it should be taught and enforced by the precepts of the chief missionaries of the church. D&C 122:5d It was not then intended, nor is it now, to burden them with the duty of looking after the disbursements of the moneys in the treasury or the management of the properties of the church, D&C 122:5e except as it may be at times necessary to do so in council with the Presidency, the high council in case of exigency, the Bishopric, bishops, or bishop''s agents abroad, or the conferences, and in accordance with the agreement hitherto made. D&C 122:5f Whatever burden the quorum may have felt rested upon them in this regard, they are now absolved from, the end designed by it having been reached, D&C 122:5g except that should it become apparent to the quorum that there was abuse in the administration of the temporal affairs of the church, they shall at once make such inquiry and examination through the proper officers of the church as will correct the evil and save the church from injury. D&C 122:6a And further the Spirit saith unto you that with the Lord one day is as a thousand years and a thousand years as a day; D&C 122:6b therefore, the law given to the church in Section 42, over the meaning of some parts of which there has been so much controversy, is as if it were given today; D&C 122:6c and the Bishop and his counselors, and the high council, and the Bishop and his council, and the storehouse, and the temple, and the salvation of my people are the same to me now that they were in that day when I gave the revelation. D&C 122:6d Nevertheless, that portion of that commandment which made it the duty of the high council to assist in looking after the poor and needy of the church was not intended to put the high council over the Bishop in the administration of the affairs of his office and calling, D&C 122:6e except as they might do so in an advisory manner and in such way that no one of the poor and the needy should be neglected; D&C 122:6f nor was it designed that the high council should dictate in the matter of purchasing lands, building houses of worship, building up the New Jerusalem, and the gathering of the people- D&C 122:6g these last named being within the province of the Presidency, the Twelve as a quorum, the councils or other officers of the branches or stakes where houses of worship are to be built, the conferences, and the general assembly of the church, and the direction of the Lord by revelation. D&C 122:6h The high council could not in justice dictate to the Bishop in direction in any of these matters and then try, and condemn, and punish him if he did not obey. D&C 122:7a The work now lying before the missionary quorums of the church is of such increased magnitude and importance-the field so white unto the harvest, and the need for laborers so great-that the Twelve and the Seventy under their direction, together with such high priests and elders as can travel and preach as missionaries, shall be free to wait upon their ministry in gospel work, D&C 122:7b leaving the branches and districts where organization is effected to the care and administration of the standing ministers-high priests, elders, priests, teachers, and deacons-so far as possible, D&C 122:7c thus freeing these spiritual authorities and leaving them at liberty to push the preaching of the word into the new fields now widening before them, D&C 122:7d in which work, if they will but now take counsel, saith the Spirit, they shall feel a peace and vigor of mind surpassing what they have enjoyed in the past. D&C 122:8a That part of the law which says, "It is the duty of the Twelve, also, to ordain and set in order all the other officers of the church," is to be understood by the revelation which went before, and in accordance with which it was written, and which follows after it in the book; D&C 122:8b and when those officers are ordained and set in their order in the church, they should be left to administer in the things unto which they were ordained, having charge of the affairs over which they are called and set apart to preside- D&C 122:8c the Twelve and Seventy administering as those prosecuting the work of preaching with the warning voice, baptizing, organizing, and setting in order, then pushing their ministry into other fields until the world is warned. D&C 122:8d It is the will of God that they do this; yea, verily, thus saith the Spirit, If they will now enter upon this work, leaving the burden of care in organized districts or conferences to the standing ministry, under the Presidency of the church, D&C 122:8e observing the law already given to ordain and set high priests or elders to preside in large branches and in districts, and also evangelical ministers, then will those officers set in the church be useful and he who gave the law be honored, D&C 122:8f the differences between the quorums be healed, confidence be restored, and good will and peace come to the people as a cherishing fountain. D&C 122:9a The quorums in respect to authority are designed to take precedence in office as follows: The Presidency, the Twelve, the Seventy in all meetings and gatherings of the membership where no previous organization has been effected. D&C 122:9b Where organization has been arranged and officers have been ordained and set in order, the standing ministry in their order: high priests, elders, priests, teachers, and deacons. D&C 122:9c The parallels are: in the Presidency, the President and his counselors; in the second presidency, the Twelve; in the missionary work, first the Twelve, second the Seventy; in the standing ministry, the Presidency; second the high priests; third the elders, then priests, teachers, and deacons in their order. D&C 122:10a Should the church fall into disorder, or any portion of it, it is the duty of the several quorums of the church, or any one of them, to take measures to correct such disorder-through the advice and direction of the Presidency, the Twelve, the Seventy, or a council of high priests, in case of emergency; D&C 122:10b and in case the Presidency is in transgression, the Bishop and his council of high priests, as provided in the law; and the Presidency and high council if the Bishop or his counselors, if high priests, are in transgression. D&C 122:10c The Scriptures and the church articles and covenants, with the rules adopted by the church, shall govern in procedure. D&C 122:11 The Spirit saith further that it is wisdom that the Presidency and Twelve in council together make such appointments as may be necessary to provide for the fields not named in the appointments made by the Presidency and recommended to the Twelve, as may be agreed by them. D&C 122:12a The Spirit saith further that Lamoni, Iowa, having been made-by the agreement of the church under the law of the land-the principal place of business of the church, it is wise and expedient that it should be considered and declared by the conference to be the seat of the Presidency of the church and in due time be made a stake. D&C 122:12b In the meantime, the district may be left to the care of its district organization, subject to the direction of the Presidency-no one of the missionary force being appointed to the charge thereof for the conference year, or longer if it shall be found advisable. D&C 122:13a The Spirit saith further: The Twelve should remain at Lamoni and continue in council with the Presidency and the Bishop and his counselors, if practicable, a sufficient time after the adjournment of conference to counsel together and agree on the things of the law and the general affairs of the church, D&C 122:13b so that when the traveling council shall separate for their several fields, there may be no longer reason for distrust, suspicion, or dissension; D&C 122:13c and if these officers will so counsel together in the spirit of moderation, and mutual forbearance, and concession, my law will be more perfectly understood by them; and a unity of sentiment and purpose will be reached by them. D&C 122:13d It is the will of your Lord and your God that this should be done. It should have been done before, but the adversary hath hindered, desiring to prevent the success of my work in the earth. D&C 122:14 For the same reasons in me that it is not expedient to fill the quorums of the First Presidency and the Twelve, who are apostles and high priests, it is not expedient that a patriarch for the church should be indicated and appointed. D&C 122:15 My servant Thomas W. Smith is in my hand; and his bishopric shall be continued for a season; if he fully recover, he will enter again into the work; if I take him unto myself, another will be appointed in his stead when the quorum is filled. D&C 122:16a And now I say unto you, mine elders, apostles, and high priests of my church: Continue ye in the ministry unto which you have been called; and if ye cannot fully agree on all the points of the law, be patient and be not contentious; so far as you can agree, work together without heat, confusion, or malice. D&C 122:16b Ye are equal in worth of position and place in the work of the church; and if in honor ye shall prefer one another, ye will not strive for precedence or place in duty or privilege, and shall be blessed of me. D&C 122:17a Yea, verily, thus saith the Lord unto the elders of the church: Continue in steadfastness and faith. D&C 122:17b Let nothing separate you from each other and the work whereunto you have been called; and I will be with you by my Spirit and presence of power unto the end. Amen. Joseph Smith', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (123, 1, 'April 20, 1894-Independence, Missouri. A joint council of the First Presidency, Quorum of Twelve, and Presiding Bishopric met as a result of the instruction given in Section 122:13. This section is not a revelation but contains the minutes of the council, which were included in the Doctrine and Covenants by direction of the General Conference. Resolutions on a variety of subjects JOINT COUNCIL D&C 123:1a In compliance with the requirement of paragraph thirteen of the revelation received during conference and by agreement between the quorums affected, the First Presidency, the Twelve, and the Bishopric met in joint council in the editor''s room of the Herald Office at nine a.m., Friday, April 20, 1894. D&C 123:1b There were present: Joseph Smith and W. W. Blair of the First Presidency; Alexander H. Smith, E. C. Briggs, James Caffall, W. H. Kelley, J. H. Lake, J. R. Lambert, Heman C. Smith, Joseph Luff, and Gomer T. Griffiths of the Twelve; E. L. Kelly, G. H. Hilliard, and E. A. Blakeslee of the Bishopric. D&C 123:2a President Joseph Smith was chosen to preside, and E. A. Blakeslee to act as secretary. D&C 123:2b A. H. Smith offered prayer, after which the President made a few remarks bearing upon the object of the council and advising forbearance and toleration in speech and feeling, regardless of the distance between those present in their judgment upon the matters under discussion. D&C 123:3 A number of questions were named and noted for discussion, and considerable informal talk was indulged in, after which resolutions were presented, discussed, and adopted in the following order-all decisions being finally made unanimous, with the sole exception noted: LAMONI COLLEGE D&C 123:4 Resolved that we look with favor upon the effort to build a college at Lamoni, to be controlled by the church. D&C 123:5 Resolved, further, that we believe it should be a purely educational institution and free from sectarian influences or bias. D&C 123:6 Resolved, further, that we give our hearty support to the present movement looking in the above direction. CHURCH HISTORY D&C 123:7 Resolved that it is the opinion of this council that there is nothing in the resolution of April, 1893, on church history that should in any way interfere with the preparation and publication of an authentic church history by the church. D&C 123:8 Resolved, further, that it is the opinion of this council that church history, both ancient and modern, may be freely used as a means of information, for what the same may be worth. DISCUSSIONS IN HERALD D&C 123:9 Whereas there seems to be a demand for a publication that may be a medium for more progressive and controversial articles for the good of the body than can be supplied by the Herald, therefore be it, D&C 123:10 Resolved that the board of publication be requested to provide for such want as soon as practicable and without injury or interference with the circulation of the Herald. UTAH CHURCH D&C 123:11a The present attitude of the Utah Church was discussed, and the council informally expressed itself as of the opinion that the ministry should boldly stand as aggressors or defensors everywhere where the questions at issue between the two churches were introduced. D&C 123:11b The Presidency received unmistakable assurance of support in their efforts to direct such controversy as might be invited by contingencies arising. LOCATING IN REGIONS ROUND ABOUT D&C 123:12 Resolved that all parties wishing to change their location be recommended to correspond with the Bishopric for information. PRESIDING COUNCILS D&C 123:13a Resolved that it is the opinion of this joint council, that the words "presiding councils" in the fourth and seventh paragraphs of Section 120 of the Book of Doctrine and Covenants refer to the traveling ministry-the Twelve and Seventy. D&C 123:13b From this decision President W. W. Blair dissented. DOCTRINAL TRACTS D&C 123:14a Resolved that the members of the Quorum of Twelve and the Presidency be requested to write tracts on such gospel topics as each may select, all of which shall be placed in the hands of the Presidency for examination, D&C 123:14b said tracts, when approved, to be placed in the hands of the board of publication to be issued as soon as possible. DIRECTING LABOR OF HIGH PRIESTS D&C 123:15 Resolved that it is the opinion of this council that high priests, when needed for missionary service abroad, may be appointed by the First Presidency, or the Twelve, or both jointly, and should labor after such appointment under the direction of the Twelve, the same as Seventies. D&C 123:16 Resolved, further, that when high priests are acting in their own standing as local presidents, they are subject to the direction and counsel of members of both the First Presidency and the Twelve, whose duty it is to regulate. D&C 123:17 Resolved, further, that when a necessity occurs for changing men or placing new men in the field between conferences to meet special exigencies, those making the appointment should notify the ministers in charge of the fields affected, if practicable, so as to avoid irregularity or possible conflict. GOSPEL BOAT D&C 123:18 Resolved as the opinion of this joint council, that Brother E. L. Kelley should proceed to San Francisco at the earliest possible time and secure the proposed boat for the Society Islands. DETROIT BRANCH D&C 123:19 Resolved that we advise that the colored members in Detroit, Michigan, be organized in a separate branch as soon as practicable. BISHOP''S COUNCIL D&C 123:20 After some deliberation the consensus of opinion of the council was secured to the effect that the words "the Bishop and his council," found in paragraph 6 of the revelation of 1894, mean the Bishop and his two counselors; and a vote obtained in support of such understanding. PRESIDENTS OF HIGH COUNCIL D&C 123:21a The following was adopted by regular vote: D&C 123:21b It is our opinion that the counselors referred to in paragraph 6, Section 99, are the counselors of the President in the Presidency of the church; but whether or not under certain circumstances the President would not be privileged to call others to assist him is a query. COUNSEL TO BE HONORED D&C 123:22a Resolved that it is the opinion of this council that the statements found in paragraphs 1, 2, and 3 of the revelation of 1894 should be understood in the same sense as paragraph 3 of the revelation of 1882 and paragraph 4 of the revelation of 1890, D&C 123:22b and that it is the duty of the Saints to honor more fully the counsel and advice of the First Presidency, the Twelve, and the Seventy in spiritual things. PRESIDENCY OF THE TWELVE AND MEANING OF THE WORD "ABROAD" D&C 123:23a The following opinion of the First Presidency, as communicated to the Quorum of the Twelve in 1890, was adopted as the opinion of this joint council: D&C 123:23b As a traveling, presiding council, your quorum has the active supervision and presidency, under the First Presidency, over the entire field of ministerial labor and control over districts, branches, and the ministry as a whole and as church organizations, and not as local presiding officers in these several organizations- D&C 123:23c holding special local presidency where no organization has been perfected-in a similar way as the First Presidency presides over the whole church, differing in this: that the First Presidency is necessarily local, while your province is not localized; D&C 123:23d nor do we mean by this that the word "abroad" is to be construed to mean foreign lands, but in the field of itinerant gospel labor everywhere, as contradistinguished from branch, district, or other local organizations. REVELATION OF 1861 D&C 123:24a Resolved that paragraph 5 of the revelation of April 15, 1894, relating to the duty of the Twelve under the authority of the revelation of 1861 (Doctrine and Covenants, Section 114), teaches that said revelation is still in force; D&C 123:24b but that whatever duty the Twelve might have felt rested upon them in "looking after the disbursements of the moneys in the treasury or the management of the properties of the church," more than what is set forth in the agreement between the Twelve and the Bishopric, as effected in April, 1878, and reaffirmed in April, 1888, or indicated in the revelation of April, 1894, they are now absolved from, the end designed by it having been reached. REQUEST FOR ARTICLES FOR PUBLICATION D&C 123:25 The Herald editors were, by vote, advised to call for articles from any who might be disposed to write upon leading gospel topics, said articles to be subjected to the inspection of the committee as heretofore named and to be accepted or rejected at its discretion. D&C 123:26 It was then ordered that the president and secretary of the council prepare the minutes of proceedings for publication in the Herald. D&C 123:27 The special business of the council having ended, Brother James Caffall expressed a desire that the usual custom of setting foreign missionaries apart by laying on of hands and blessing be observed in his behalf, as he had been appointed to labor in Europe. D&C 123:28a The council then knelt and was led in prayer by President Joseph Smith, who earnestly invoked the divine blessing upon Brother Caffall and his labors, after which Brethren Joseph Smith, W. W. Blair, A. H. Smith, and E. L. Kelley laid their hands upon him and set him apart, President W. W. Blair being mouth in supplication. D&C 123:28b The Spirit of the Master fell upon those present, and the service and season was one of joyful solemnity and peace. "Redeemer of Israel" was then sung and the benediction pronounced by President Joseph Smith. D&C 123:29a Thus ended the work of the council convened in accordance with the requirement of the revelation which had been formerly accepted by the church. D&C 123:29b All present were convinced that the appointment had been wisely made and that the results were and would be such as would fully attest the divinity of the call. D&C 123:30a The sessions continued until the afternoon of the 25th, adjournment being had about four o''clock. D&C 123:30b Brother Gomer T. Griffiths was excused and left for home on the 23rd, and Brother E. A. Blakeslee at noon on the 25th. Brother Joseph Luff was then chosen secretary for the closing session. D&C 123:31a To God, whose hand has led us and whose patience has borne with our infirmities, the generous praise of his church is due. D&C 123:31b May our renewed consecration, under the better conditions his mercy has brought about, bring to him added glory and to his church prosperity and peace. Joseph Smith, President Joseph Luff, Secretary', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (124, 1, 'April 8, 1897-Lamoni, Iowa. Revelation through Joseph Smith III, addressed to the leading quorums and to the church in general. The Presidency was temporarily filled; and, for the first time since 1860, the Quorum of Twelve and the office of Presiding Patriarch were filled. Alexander H. Smith called to be Presiding Patriarch-Callings to various offices-Vision of the organization of the quorums of Seventy-Sons of leading officers are admonished to be faithful in the work of the church By the grace of God and the Lord Jesus Christ, I am permitted to write unto you and the church in answer to prayer. On the night of the 7th of April in the year of our Lord 1897, and on the morning of the 8th, I was in the Spirit and was commanded to write and say unto the elders and the church: D&C 124:1 Thus saith the Spirit of your Lord and Savior Jesus Christ: Your fasting and your prayers are accepted and have prevailed. D&C 124:2a Separate and set apart my servant Alexander Hale Smith to be a counselor to my servant, the President of the church, his brother, and to be patriarch to the church and an evangelical minister to the whole church. D&C 124:2b Also, appoint my servant E. L. Kelley, Bishop of the church, to act as counselor to the President of the church for the conference year or until one shall be chosen to succeed my servant W. W. Blair, whom I have taken unto myself- D&C 124:2c he to sit in council with his brethren of the Presidency and act with and for them and the church, though he shall still be and act in the office of his calling of Bishop of the church with his brethren of the Bishopric. D&C 124:3 The Quorum of Twelve, my servants, may choose and appoint one of their number to take the place of my servant Alexander H. Smith; and if they shall choose William H. Kelley from among them for this place, it will be pleasing unto me; nevertheless, if directed by the spirit of revelation and wisdom, they may choose another. D&C 124:4a And, that the quorum may be filled and be prepared to stand as a unit in the councils of the church, in equality with the Presidency and the Seventy, choose and set apart to act as apostles in the Quorum of Twelve my servants I. N. White, J. W. Wight, and R. C. Evans, for they are called unto this office and calling. D&C 124:4b And, if these will accept this appointment and remain humble, faithful, and diligent, they shall with their brethren be greatly blessed in ministering the word and bringing souls unto me. Let the quorum be not doubting but believing; and I, the Lord, will bless them. D&C 124:5a My servants, the presidents of the Seventy, may with the consent and approval of their brethren of the Seventy, sitting in council together, select from their brethren one to take the place of my servant I. N. White, if he accept the appointment to the Quorum of Twelve and his choosing be approved by the church; D&C 124:5b and in like manner they may fill any other vacancy that has occurred or may occur, such selection and appointment to be made in the spirit of prayer, and supplication, and wisdom and to be approved by the church. D&C 124:6a It is according to the vision that the seven presidents of the Seventy shall preside over the whole number of the Seventy when assembled in council together; D&C 124:6b the senior, or chosen president of the seven presidents, shall preside over the six other presidents in their councils as presidents of the Seventy; D&C 124:6c and when either quorum is sitting in council, as a quorum, then its chosen president shall preside over its sittings. D&C 124:6d When any quorum of the Seventy may be sitting, any one or all of the seven presidents may, at their request or by invitation of such quorum, be present and take part in the deliberations of such council; but the president of such quorum only shall preside, except by consent of the quorum obtained by vote properly taken. D&C 124:7a The sons of my servant, the President of the church, the sons of my servant William W. Blair, whom I have taken to myself, the sons of my servant, the Bishop of the church, and the sons of my servants of the leading quorums of the church are admonished- D&C 124:7b that upon their fathers is laid a great and onerous burden; and they are called to engage in a great work, which shall bring them honor and glory or shame, contempt, and final great loss and destruction, D&C 124:7c as they shall in uprightness, faithfulness, and diligence discharge their duties acceptably to God or shall in carelessness, slothfulness, or wickedness fail in their calling and ministry therein; D&C 124:7d and to their sons shall come honor or shame as they shall approve or disapprove themselves to God. D&C 124:7e These sons of my servants are called; and, if faithful, shall in time be chosen to places whence their fathers shall fall, or fail, or be removed by honorable release before the Lord and the church. D&C 124:8a The Spirit saith further unto the church, Be of good cheer. D&C 124:8b It has pleased the Father to accept many of the sacrifices of his people; and, notwithstanding some have fallen while engaged in their work, some have been tried and are still tried; some have been and are afflicted, yet the Lord has seen the affliction and trial and will accept and bless; and no man shall lose his reward. Brethren of the ministry and members of the church: My soul has been cheered, my spirit and body have been strengthened, and my heart made exceeding glad by the blessed and holy influence of the Spirit which was with me and still is with me as I write-causing me to give praise, honor, and glory to God and the Lamb, to whom honor and glory belong and with whom are might, power, and dominion evermore. Amen. Your servant for the Christ''s sake, Joseph Smith President of the Church Lamoni, Iowa, April 9, 1897', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (125, 1, 'April 15, 1901-Independence, Missouri. Inspired counsel through Joseph Smith III. Vacancy filled in the Quorum of Twelve-Duties of the patriarchs, who are evangelical ministers-Rules of representation at General Conference-Independence and Lamoni Stakes are to be organized-Tracts are to be written-Instruction on foreign missions-Exercise discernment regarding spiritual manifestations STATEMENT AND REVELATION Before entering further upon the business, I have something to present. I spent a sleepless night. After retiring to my rest, weary, as you must know, I engaged in a season of prayer quietly, as I had been doing all day; and I suddenly found myself very wide awake; and from that on, I was in the Spirit, the Spirit of inspiration burning in my breast; and by it I was bidden to come to the house of assembly and tell what was given to me of light and instruction. I trust that it shall be so to you. VACANCY IN THE PRESIDENCY D&C 125:1 The successor of my servant W. W. Blair is with the body; but the conditions are not ripe for this addition to the presidency, but it shall be made in due time. In the meantime, let the presidency continue as at present constituted. VACANCY IN THE TWELVE D&C 125:2 To fill this vacancy, I was instructed to present the name of "my servant Peter Andersen." EVANGELICAL MINISTERS D&C 125:3a The patriarch is an evangelical minister. The duties of this office are to be an evangelical minister; to preach, teach, expound, exhort, to be a revivalist; and to visit branches and districts as wisdom may direct, invitation, request, or the Spirit of God determine and require; D&C 125:3b to comfort the Saints; to be a father to the church; to give counsel and advice to individuals who may seek for such; to lay on hands for the conferment of spiritual blessing, and if so led, to point out the lineage of the one who is blessed. D&C 125:4a He is to be free from responsibility-ministerial-as a traveling minister and from the care of the local branch or church and district affairs. D&C 125:4b When traveling and preaching, holding revival meetings, he is to labor in connection with the branch and district officers, not subject to the ministerial control of the missionary in charge, except he should transcend his bounds and teach false doctrine or be found in transgression. D&C 125:4c He is not to meddle with branch affairs or district affairs. D&C 125:4d He is not to listen to complaints made by individuals to him; but if persons insist upon presenting their troubles, he is to request them and require them to make them in writing, signing the name, giving time, place, and character of the trouble, with the witnesses, which it will be his duty to present to the branch or district officers, as the case may require. D&C 125:4e He is not to be put in charge of either branch or district. These are the privileges which attach to the office of patriarch and evangelical minister. D&C 125:5a The Presiding Patriarch is to be considered the first, and when patriarchs meet in council, is to preside. D&C 125:5b Besides these duties, the patriarch may meet with quorums in their quorum meetings, where he may be asked for counsel, but will not have either voice or vote, except by courtesy, having no direct control of quorums. D&C 125:6a Other evangelical ministers beside the Presiding Patriarch have similar duties in the districts where they are appointed. D&C 125:6b Revelations have been given, as my people know, that these men should receive ordination; but hitherto those upon whom this burden has lain have neglected, for the reason that they did not understand the duties and prerogatives that attach to the office. Let my servants take heed and hesitate no longer. RULES OF REPRESENTATION D&C 125:7a My servant was directed to present to the church rules of representation, and he so stated to the body at different times that he was so led; but the conferences of my people saw proper to change these articles and rules of representation, and propositions are pending that they be still further changed. D&C 125:7b The direction of the Spirit is that they be left as they now are until such time as the increased numbers of the members of the church shall require either an enlargement of the number entitled to delegate or that there may be a closer line drawn as to the number of delegates which the church shall require to meet. D&C 125:8 The word elders used in the law signifies those holding the Melchisedec priesthood only; all classes and orders of this priesthood are characterized by the word elder. D&C 125:9 The only qualification for delegates chosen by the branches or districts should be membership and good standing, it being given by the Spirit that those other than the eldership should be represented in this way. STAKES D&C 125:10a My people are directed to establish two stakes-one at Independence, one at Lamoni, Iowa-organizing them after the pattern which is found in the law: a presiding high priest with counselors, a high council, and a bishop and his counselors. D&C 125:10b These stakes shall be made to comprise the boundaries of the districts as they now stand, the center at the towns and places named; D&C 125:10c and the majority of the councils that should be chosen should be residents of the places named in order that there may ever be a sufficient body to transact the business required. TRACTS D&C 125:11a It is the duty of the church to provide tracts in the Scandinavian, German, Chinese, Japanese, and Portuguese languages, and others, as the missions may require- D&C 125:11b these tracts to be written by those in the ministry and those of the brothers who are not of the ministry who have a talent for writing and to be submitted to the Presidency before being published. D&C 125:11c They should be short, clearly stated; and a sufficient number should be printed to furnish the traveling ministry with the quantities desirable for them to distribute. FOREIGN MISSIONS D&C 125:12a The missions abroad, other than those in the land of Joseph which were opened officially during the lifetime of the martyrs, shall be considered as having been opened unto us, whether they were at once undertaken and prosecuted during the lifetime of the martyrs, or whether subsequent to their death they were prosecuted in righteousness-wherever they were sent. D&C 125:12b Other missions not thus opened, it will be requisite that the Twelve shall either go or, in the exercise of their missionary authority, send, as provided in the law, of the Seventy. D&C 125:13a For prosecuting the work in two of these missions, this is offered and directed: D&C 125:13b Send the Bishop to England with my servant Gomer T. Griffiths to aid in arranging the affairs of the church there, organizing the ministry locally and determining what help in the missionary field may be required from America. D&C 125:13c Authorize the selection and the ordination of a high priest to officiate in the office of bishop in England, that it may be accomplished as soon as practicable and without fail, in answer to the request made by my servants in that land. D&C 125:13d Authorize the patriarch, as one of the Presidency, to visit Australia and the islands of the sea, the Society Islands, authorizing him to assist the authorities there in arranging their missionary labor by his advice, D&C 125:13e and also selecting and ordaining a high priest to act in the office of bishop, carrying with him the authority of the conference. D&C 125:14a Branches and districts are to be conducted according to the rules given in the law as directed in a former revelation: They shall take the things which have been given unto them as my law to the church to be my law to govern my church. D&C 125:14b And these affairs are not to be conducted by manifestations of the Spirit unless these directions and manifestations come through the regularly authorized officers of branch or district. D&C 125:14c If my people will respect the officers whom I have called and set in the church, I will respect these officers; and if they do not, they cannot expect the riches of gifts and the blessings of direction. D&C 125:15a Prophesying over them that are sick in administering to them has been a fruitful source of trouble among my people. D&C 125:15b They must observe that this they are not required to do except there be a direct manifestation of the Spirit which may direct it. D&C 125:15c Pray over the sick, anoint them with oil as commanded in the law, and leave them in my hands, that the Spirit may deal with them according to my wisdom. D&C 125:15d Many spiritual manifestations have been had. Some of these have been false; and under the operation of the law which I gave many, many years ago, those who make these false presentations are not to be feared among my people. D&C 125:15e They are not justified in permitting their human sympathies to overcome that which has been written in my Scriptures. The spirit of the prophets is subject to the prophets. D&C 125:16a The college debt should be paid; the ministers going out from the conferences held by the elders of my church are not expected or authorized to throw obstacles in the way of the accomplishment of that which has been intrusted to the Bishopric to pay this great debt. D&C 125:16b Their right to free speech, their right to liberty of conscience, does not permit them as individuals to frustrate the commands of the body in conference assembly. D&C 125:16c They are sent out as ministers to preach the gospel. And their voices-if opposed to what may be presented to the conference-should be heard in the conferences and not in the mission fields, to prevent the accomplishment of the object with which the officers of the church have been intrusted.', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (126, 1, 'April 16, 1902-Lamoni, Iowa. A prophetic vision and revelation received by Joseph Smith III. Counsel concerning the leading quorums of the church-Application of the law of tithing and consecration-Quorums of Presidency, Twelve, and Seventy in joint council are to safeguard the rights of the people To the Officers and Members of the Conference: D&C 126:1 On the night of April 16, I made the condition of the church a subject of prayer, intensely desirous of receiving light and information in relation thereto and my duty. I awoke at the hour of three and had in presentation the following vision: D&C 126:2a I saw the assembly of the Saints and the general authorities, the latter being arranged upon a platform with the seats arranged in lines, each line from the front of the platform slightly raised to the rear. D&C 126:2b On that platform I saw the Quorum of the Presidency, the Bishopric, the Twelve, and a line above the Twelve on the seat behind them, a number of the brethren, including four of the present members of the Twelve and the patriarchs now ordained and recognized in the church. D&C 126:2c The Quorum of the Twelve was filled, and the places of the four whom I saw on the upper tier of seats were occupied by others known to the church. D&C 126:3 I asked the question who these men occupying the upper row of seats were; and I was told that they were evangelical ministers, called to minister in spiritual blessings to the church and to preach the gospel undeterred by the burden of the care and anxiety of presiding over missions and districts. D&C 126:4 I saw in the Presidency two known to the church but who have not hitherto been connected with the Presidency. D&C 126:5a I saw the Bishopric as at present constituted, with the attendant bishops upon either side. I asked what was the meaning of this. D&C 126:5b I was told that the Bishop should not be burdened with the spiritual care of the church except as such might be brought before him in pursuance of the law which provided for the bishop''s court. D&C 126:6 I then asked what was meant by the choosing of members for the Presidency so young in years. I was informed that it was for the purpose that, before the Presidency should be invaded by death, these younger men should be prepared by association to be of assistance to whosoever should be chosen as the President upon the emergency which should occur. D&C 126:7a The names of those of the present Quorum of Twelve whom I saw upon the upper tier of seats were James Caffall, John H. Lake, Edmund C. Briggs, and Joseph R. Lambert. These were sitting with the other evangelical ministers. D&C 126:7b Those whom I saw sitting with the Quorum of the Twelve were Frederick A. Smith, Francis M. Sheehy, Ulysses W. Greene, Cornelius A. Butterworth, and John W. Rushton. D&C 126:8 Sitting with the Presidency were Frederick M. Smith and Richard C. Evans. D&C 126:9 The assembly seemed to be large and orderly, with the different officers of the church in their quorums assembled in much the same order as observed at our annual conferences, but did not seem to be so large as at other times I had seen them. D&C 126:10a In regard to the gathering and the work of the Bishopric in regard to the law of tithing and consecration, I made inquiry what should be the attitude of the church in regard thereto. D&C 126:10b To this question I was answered that the Book of Doctrine and Covenants as accepted by the church was to guide the advice and action of the Bishopric, taken as a whole, each revelation contained therein having its appropriate bearing upon each of the others and their relation thereto; D&C 126:10c and unless the liberties of the people of the church should be in jeopardy, the application of the law as stated by the Bishopric should be acceded to. D&C 126:10d In case there should be a flagrant disregard of the rights of the people, the quorums of the church in joint council should be appealed to, and their action and determination should govern. D&C 126:10e I inquired what quorums of the church were meant; and I was answered, the three quorums, the decisions of which are provided for in the law: the Presidency, the Twelve, and the Seventy. D&C 126:11 In case of transgression in his office, the Bishop should be called in question before the council which is provided for in the law, to which court all the general officers of the church are to be subject. D&C 126:12 After much thought and pondering upon what I had seen as related above, together with the information contained in the answers to my inquiries, I did not see my way clear to present the matters therein contained in yesterday''s session until the church had by its votes sustained the officers of the quorums referred to. D&C 126:13 It will be seen that there is an apparent invasion of the rule which has been supposed to govern the selection of evangelical ministers, but for this I am not responsible; and the whole matter is hereby submitted for the approval or disapproval of the church. Joseph Smith Lamoni, Iowa April 18, 1902', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (127, 1, 'April 14, 1906-Independence, Missouri. Revelation through Joseph Smith III regarding temporal ministry. Establish a sanitarium to care for the sick, with Apostle Joseph Luff to be medical director-Establish a home for children-Joseph Burton to minister in the South Sea Islands-Counsel on the gathering-Designation of Frederick M. Smith as successor to Joseph Smith III Thus saith the Spirit unto the Church: D&C 127:1a It is the will of the Lord that a sanitarium, a place of refuge and help for the sick and afflicted, be established by the church at Independence, Missouri, as my servant Joseph Smith has already stated to you. D&C 127:1b This should be done as soon as it is found to be practicable and without unnecessary delay. D&C 127:1c The Presiding Bishop and his counselors and the Bishopric of the Independence Stake should take counsel together in locating and establishing this sanitarium. D&C 127:2a It is also expedient that these should be assisted by the advice and counsel of one of my servants who is acquainted with the laws of health and the practice of medicine and who may have charge when the institution is established. D&C 127:2b It is in accordance with the instruction given to my servant Joseph Smith that my servant Joseph Luff, who has been giving his attention to the study of medicine and has been preparing himself for usefulness in this direction, be associated with this sanitarium as a medical director and physician to the church and be put in charge, D&C 127:2c that he may be an assistant to those who seek the aid of this institution of the church in his spiritual office and his calling as a physician, D&C 127:2d with those who from time to time may be called to administer in laying hands upon the afflicted and sick, where they may be removed from the influences and environments unfavorable to the exercise of proper faith unto the healing of the sick. D&C 127:2e And this my servant Joseph Luff may do and retain and exercise his apostleship. D&C 127:3 There should also be a home for children established; and the efforts of the Daughters of Zion should be approved and carried unto completion as soon as is consistent with the necessary demands of the work of the church in other directions. D&C 127:4a In the establishment of the sanitarium and the home for children, debt should not be contracted nor too large nor expensive buildings be built at the outset. D&C 127:4b Those to whom this work is assigned should exercise the necessary degree of wisdom, that the work be effectual for the intent and purposes designed. D&C 127:5a It is necessary that some, one or more, be sent to the South Sea Islands. The heaving of the sea beyond its bounds has been trying to the faith of many of the Saints in that far-off region. D&C 127:5b They should be visited, and comforted, and encouraged. D&C 127:5c Someone of experience and knowledge of the situation should be sent, accompanied by another, who should be prepared to make a stay of years, if necessary, in the mission to those islands. D&C 127:5d My servant Joseph F. Burton, though aged, will be an efficient officer and representative of the faith and, choosing someone to go with him, may be intrusted with this difficult mission. D&C 127:6 It is the will of the Lord that the mission to Utah and the west should be continued and suitable representatives of the church be sent and maintained there under the conditions prevailing at the present time. It is essential that the church have proper representatives there. D&C 127:7a As the Saints have heretofore been instructed in reference to the gathering, they are now again admonished that the gathering must not be in haste nor without due preparation, D&C 127:7b and must be done in accordance with the revelation given to the church upon Fishing River and in accordance with the counsel and advice of the elders of the church whose duty it has been made to counsel and advise the Saints. D&C 127:7c The spirit of speculation, the exhibition of greed for gain, is unseemly in the Saints and officers of the church and should be avoided. It has the appearance of evil. D&C 127:7d Heed should be paid to the admonitions of those who from time to time preach and write upon the gathering-to remove the principle of selfishness from the hearts of the Saints and especially from those upon whom rests the burden of the church and its ministrations abroad. D&C 127:8a Inasmuch as misunderstanding has occurred in regard to the meaning of a revelation hitherto given through my servant Joseph Smith in regard to who should be called to preside in case my servant should be taken away or fall by transgression, D&C 127:8b it is now declared that, in case of the removal of my servant now presiding over the church by death or transgression, my servant Frederick M. Smith, if he remain faithful and steadfast, should be chosen in accordance with the revelations which have been hitherto given to the church concerning the priesthood. D&C 127:8c Should my servant Frederick M. Smith prove unstable and unfaithful, another may be chosen according to the law already given. Independence, Missouri April 14, 1906', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (128, 1, 'April 18, 1909-Lamoni, Iowa. Inspired counsel given by Joseph Smith III to the elders concerning procedures and organizations for Zionic activities. Authority of the Bishop and his counselors in the work of gathering-Organizations to operate according to laws of the land-Be in the world but not of it To the Eldership: Brethren: So far as the burden of the conference and its peculiar conditions have enabled me to do, I have steadfastly presented the matter stated by the Bishop for our consideration to the Lord for instruction. Whether that which has come to me will bring relief to the situation, I know not; but such as it is, I hereby present it. D&C 128:1a The conditions surrounding the work, the increase of the membership of the church, the increasing desire for gathering together, and the necessity existing for the obtaining places for settlement in the regions round about, D&C 128:1b under the existing laws of the United States, and especially the state of Missouri, require that the Bishopric be authorized to take such measures as will bring to pass the organization of those who are desirous and willing to form parts in colonization under terms of association in different localities, D&C 128:1c where settlements may be made and may lawfully secure and hold property for the benefit of themselves, and their fellow church members, and the whole body of the church when organized. D&C 128:2a The work to be done belongs to those who are by command of God made the custodians of the properties of the church; D&C 128:2b and these by their appointment are empowered to prosecute the work of caring for and using such properties as are confided to their care to accomplish the end designed. D&C 128:3a The Bishop and his counselors, together with the other bishops of the church and such other officers as the Bishop may call together, with whom he may confer in council, are authorized to devise the methods of procedure; D&C 128:3b and they will be guided by the spirit of wisdom and revelation to do the work intrusted to their care. D&C 128:4a Counsel has already been given to those gathering into the regions round about to consult with the elders and the bishops before removing into those regions, D&C 128:4b that such removal may be accomplished through the having of all things prepared before them who seek to remove and become resident in the regions round about. D&C 128:5 It is well to understand that the term "regions round about" must mean more than a small area of country round about the central spot and that the necessity of the great majority of the church in gathering together can only be provided for by settling carefully together, as many in one region as may be practicable, and profitable, and in accordance with the feelings of the people under the laws existing in the places where such settlements are to be made. D&C 128:6a The great variety of callings, avocations, and professions will present difficulties precluding the practicability of all settling and living in near proximity to each other. D&C 128:6b It is therefore within the province of those upon whom the burden of organization may rest to provide for other organizations or associations than those simply pastoral or agricultural. D&C 128:6c Under this head there may be placed industrial associations of such sorts as the varied qualifications existing among workmen may demand. D&C 128:7a It has been prophesied that the Gentiles shall assist in rebuilding the waste places of Zion. D&C 128:7b This cannot refer to the inhabitants of Zion who are the pure in heart, but must refer to the places which have been occupied, or which it may be contemplated to occupy, in the regions round about. D&C 128:7c The Saints cannot occupy in any place on the land of Zion which is not under the domination of civil law; and as citizens of the state, holding their liberties under the law, there must be a proper recognition and observance of these laws. D&C 128:7d The Lord has said that this condition of obedience to law must continue until he comes, whose right it is to come, and assumes to reign over his people. D&C 128:7e Under the provisions of the laws, these organizations or associations must be instituted and carried to completion if they shall be of benefit to those who shall be engaged in them. D&C 128:8a The Spirit saith further: That these organizations contemplated in the law may be effected and the benefits to be derived therefrom be enjoyed by the Saints-in such enjoyment they cannot withdraw themselves so completely from a qualified dependence upon their Gentile neighbors surrounding them as to be entirely free from intercommunication with them; D&C 128:8b yet it is incumbent upon the Saints, while reaping the benefits of these organizations, to so conduct themselves in the carrying into operation the details of their organizations as to be in the world but not of it, D&C 128:8c living and acting honestly and honorably before God and in the sight of all men, using the things of this world in the manner designed of God, that the places where they occupy may shine as Zion, the redeemed of the Lord. D&C 128:9 The Bishop should be directed and authorized to proceed as soon as it shall be found practicable by consultation with the general authorities of the church, who are made the proper counselors in spiritual and temporal things, to carry out the provisions of the law of organization which are by the law made the duty of the Bishop. Joseph Smith Lamoni, Iowa, April 18, 1909', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (129, 1, 'April 18, 1909-Lamoni, Iowa. Revelation to the church through Joseph Smith III. Vacancies filled in the Presidency and Quorum of Twelve-Appointments to various offices-Offices and orders within the Melchisedec priesthood-Counsel of the Bishopric regarding the temporal law is to be followed-Unity is commended To the Church: After constant meditation and prayer, both before and after coming to conference and during the sessions, so far as the peculiar conditions obtaining in our sittings had permitted, I was in the Spirit during the nights of the 15th and 16th of the month and the day passing between at such times during the calm that occasionally ensued and the quiet of the night when the burden of my care forbade sleep. My dreams also have been enlightening and encouraging. D&C 129:1a The voice of the Spirit to me is: Under conditions which have occurred, it is no longer wise that my servant R. C. Evans be continued as counselor in the Presidency; D&C 129:1b therefore, it is expedient that he be released from this responsibility and another be chosen to the office. He has been earnest and faithful in service, and his reward is sure. D&C 129:2a My servant Joseph Luff cannot fulfill the duties of a member of the Quorum of Twelve, in actively looking after and caring for the missionary work in the field, and discharge the duties of his calling as a physician, ministering to the many seeking his advice and aid, with safety to himself and others. D&C 129:2b It is wise, therefore, that the church release him from the responsibilities of the active apostleship as a member of the quorum, that he may act unreservedly in his calling. D&C 129:2c Another may be chosen to the office in the quorum. He has been faithful, and his record and reward are in my hand. D&C 129:3a That the historian of the church, my servant Heman C. Smith, may more freely and efficiently pursue his duties and privileges as historian, the church may release him from the burden attendant upon him as an apostle in the quorum and choose another to occupy therein. D&C 129:3b He has been long in the service, has done his duties well in the spirit of self-sacrifice, and his reward is with me. He will be blessed in diligent service in his calling as historian when relieved of the double responsibility. D&C 129:4 These, my servants, who are relieved from their responsibilities of the quorum work, have wrought well in their service with their fellow-servants and must retain their right to labor in the ministry, holding the high priesthood and entitled to all that appertains to that calling when need requires or wisdom directs. D&C 129:5 The Spirit saith further to me: To fill the vacancy caused by the releasing of Counselor R. C. Evans, present the name of my servant Elbert A. Smith, the son of my servant David H. Smith, who was taken and who awaits his reward, to be chosen, appointed, and ordained as counselor to my servant Joseph Smith and to be one of the Presidency. D&C 129:6a The Spirit saith further: In order that the places of those taken from the Twelve may be supplied and the quorum filled, that it may act as a whole, my servants J. F. Curtis and Robert C. Russell may be chosen and set apart to the office of apostle and be enrolled and sustained in the quorum. D&C 129:6b Other servants there are who will be called and appointed ere long, but not now. D&C 129:7a Those who are holding the office of patriarch are to be enrolled with the high priests, the same as the bishops, who are acting in their office by virtue of their being high priests. D&C 129:7b These men in their office are an order in the priesthood, the same as the high councils of the church and the stakes, and as the bishops who hold as high priests, as the quorum of the twelve, and as the Presidency are but orders in the priesthood-there being but two priesthoods; and these are orders in the Melchisedec priesthood. D&C 129:7c There is no difference in the priesthood, though there may be and is in the office in which the several orders may occupy and act. D&C 129:8a The Spirit saith further: The attention of the church is called to the consideration of the revelation, given in answer to earnest supplication, with regard to temporal things. D&C 129:8b The word has been already given in agreement with revelations long since delivered to the church, that the temporalities of the church were to be under the charge and care of the Bishopric-men holding the office of bishop under a presiding head acting for the church in the gathering, caring for, and disbursing the contributions gathered from the Saints of moneys and properties under the terms of tithing, surplus, free will offerings, and consecrations. D&C 129:8c The word which has been given at a late period should not have been so soon forgotten and disregarded by the church or any of its members. D&C 129:8d "I am God; I change not" has been known to the church and the eldership since the coming of the angel with the message of restoration. D&C 129:8e Under it the church has sought the Lord and received from time to time that which was deemed sufficient for the time to govern the church and its ministers, both of the spiritual and the temporal divisions of the work. D&C 129:8f The church has been directed to accede to the rendition of the Bishopric with respect to the temporal law; D&C 129:8g and until such heed is paid to the word which has been given, and which is in accordance with other revelations given to the church, which had been before given, the church cannot receive and enjoy the blessings which have been looked for when Zion should be fully redeemed. D&C 129:8h Therefore, hearken once again unto the voice of inspiration in warning and instruction, and conform to that which is given, and receive what is awaiting the upright and the pure in heart. D&C 129:9a The Spirit saith further unto the church: The Lord is well pleased with the advancement which has been made in approaching unity during the conference year; D&C 129:9b and though there may have been differences of opinion, these differences have been held in unity of purpose and desire for the good of my people and will result in helping to bring to pass a unity of understanding. D&C 129:9c So be ye encouraged, and press on to the consummation designed of God for his people-unity, honor, sanctification, and glory. Amen. Joseph Smith Lamoni, Iowa, April 18, 1909', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (130, 1, 'April 14, 1913-Lamoni, Iowa. Revelation to the church through Joseph Smith III. Appointments to various offices-Exercise the principles of sacrifice and repression of unnecessary wants-Warning against the spirit of accusation D&C 130:1 In obedience to the spirit and design of the day of fasting and prayer, I observed the day with the church. I have hitherto made supplication to the God whom we serve and renewed my supplication in the spirit of the desire of the church for instruction and light. And I am now prepared to lay before the church what has come to me as the presiding officer, through whom the Master may speak to his people. D&C 130:2a Thus saith the voice of the Spirit: In order that the Quorum of Twelve may be placed in better condition to carry on the work of the ministry in various fields of occupation, D&C 130:2b it is expedient that Elders W. H. Kelley, I. N. White, and J. W. Wight be released from the active duties of the apostolic quorum on account of increasing infirmities of age and incapacity caused by illness of body, D&C 130:2c and stand with their associates among the high priests and patriarchs of the church for such special service as may be open to them, according to wisdom and the call of the Spirit. D&C 130:3a It is also expedient that Elder Frederick A. Smith be released from the quorum activities, that he may take the place of his father, Elder Alexander H. Smith, as the Presiding Patriarch of the church. D&C 130:3b According to the tradition of the elders, he should be chosen and ordained to this office, thus releasing Elder Joseph R. Lambert from the onerous duties in which he has faithfully served since the death of the Presiding Patriarch. D&C 130:4a To fill the vacancies caused by the release of these elders from the apostolic quorum, Elders James E. Kelley, William M. Aylor, Paul M. Hanson, and James A. Gillen may be chosen and ordained as apostles to take, with others of the quorum, active oversight of the labors in the ministerial field. D&C 130:4b These servants, so called and chosen, if faithful, will receive the blessings which those have enjoyed who have preceded them in the apostolic quorum, D&C 130:4c and will be entitled to receive such ministration of the Spirit as will continue to qualify them for the discharge of the duties of the position whereunto they are called. D&C 130:4d The Twelve in its reorganization for its work may choose its own officers (president and secretary) by nomination and vote. D&C 130:5a The Spirit saith further: Elder E. A. Blakeslee is hereby called into the more active participation of the duties of the Bishopric than he has hitherto engaged in, D&C 130:5b in order that he may give such assistance to the Bishop, E. L. Kelley, as is essential unto the success of the work intrusted to the Bishopric. D&C 130:5c It is also expedient that he be ordained unto the office of bishop, that he may serve as did his father, George A. Blakeslee, who has preceded him. D&C 130:6a The Spirit saith further: That the Bishopric may be still further put in condition to perform the duties of the office of caring for the temporalities of the church, the imminent necessity of which appears clear to all, D&C 130:6b the church should authorize the Presiding Bishop to make choice of someone who may be qualified to take active participation in the work of the Bishopric and become in due time a part thereof; D&C 130:6c and this one so chosen should receive the support and sanction of the church until he shall have approved or disapproved himself as a servant of the Master in the office whereunto he shall be called. D&C 130:7a The Spirit saith further unto the church assembled and at large: D&C 130:7b In order that the temporal affairs of the church may be successfully carried on and the accumulated debt of the church in its respective departments where debts have accumulated may be properly met and in due time discharged, D&C 130:7c the church is instructed, both as members and as the body at large, to avoid the unnecessary building of houses of worship or places of entertainment or otherwise expending the tithes and offerings of the church in that which may not be essential unto the continued onward progress of the general work; D&C 130:7d and both in private and in public expenditure carry into active exercise the principle of sacrifice and repression of unnecessary wants; D&C 130:7e and thus permit the accumulation of tithes and offerings in such amounts as may be needful to properly discharge the existing indebtedness of the church as a body. And the Spirit counseleth the church in this regard. D&C 130:8a The Spirit saith further: That the elders and delegates assembled in business capacity are counseled to cease permitting the spirit of recrimination and accusation to find place in their discourse, either public or private, D&C 130:8b as it tends to destroy confidence and create distrust, not only in those present at councils where they occur but to those to whom the knowledge of such a course of procedure comes by the voice of those who are present and witness what is said and done. D&C 130:8c There should be harmony; and the Spirit enjoins it upon all, that the Master may be remembered as in meekness and due sobriety he carried on the great work to which he was called. D&C 130:9a The Spirit saith further: That the church has been warned heretofore that the sons of the leading officers of the church are called and may be chosen to the respective offices to which the Spirit may direct. D&C 130:9b And the church should be prepared when necessity arises to properly choose such officers as may be pointed out as those who should fill the positions to which they are respectively called. D&C 130:9c There are others still in reserve who are fitted, through the testimony that Jesus is the Christ and the doctrine is true, to serve as those who are sent as apostles of peace, life, and salvation to those who are laboring in the valleys of humiliation and distress of spirit. Lamoni, Iowa April 14, 1913', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (131, 1, 'April 14, 1914-Independence, Missouri. The last revelation given to the church through Joseph Smith III before his death on December 10, 1914. Counsel to the Bishopric-Counsel against spreading suspicion and distrust D&C 131:1a In agreement with the notice for the general fast of the church to be observed on the first Sunday, being the fifth day of April, 1914, I, Joseph Smith, President of the church, in common with the custom of the brotherhood, observed the rule requiring the fast and spent that day in meditation and prayer upon the work of God and our present duty in the affairs intrusted to our care. D&C 131:1b Before the hour of breaking the fast came, I was blessed by the presence of the Holy Spirit resting upon me in quiet assurance and in power. D&C 131:1c In the still, small voice which giveth light and understanding to the intelligence of man, exalting the soul and sanctifying the spirit, there came unto me the directing voice of him whose work we are engaged in. D&C 131:2a Thus saith the Spirit unto the church: The time has now come when the necessities of the work require that the servants of the church, Bishops Edwin A. Blakeslee and Edmund L. Kelley, should be more closely associated in the carrying on of the financial affairs of the church and caring for the various organizations requiring the expenditure of moneys collected from the membership of the church and the care of the properties belonging to the church as an organization under the laws of the church and of the land. D&C 131:2b To accomplish this object, the servant of the church, Edwin A. Blakeslee, should make himself more thoroughly acquainted with the affairs in the office of the Bishopric, that he may be better prepared to advise, strengthen, and aid in controlling the affairs of the Bishopric to the successful accomplishment of the object in view when he was called and ordained to the Bishopric. D&C 131:3a The Spirit saith further that it is expedient that additional aid be given to the Bishopric in charge of the general affairs of the finances; D&C 131:3b and to do this, Richard C. Kelley, son of my servant Bishop Edmund L. Kelley, should be called and ordained to the office of an elder, that he may act with the Bishopric in case of necessities and to work in the office of the Bishop in looking after and caring for the affairs appertaining to that office; D&C 131:3c and in due time, if he approve himself in this work, he should receive an ordination to the high priesthood which would authorize him to act fully as a part of the Bishopric. D&C 131:4a The Spirit saith further that the spirit of distrust and want of confidence in those who are called and ordained to act in the various responsible positions in the priesthood and in authority in the church is unbecoming those professing faith in God, Jesus Christ, his Son, and the Holy Spirit of truth, and evinces a serious lack of that charity which Paul, an apostle of Christ, declared to be the quality of Christian virtue which thinketh no evil. D&C 131:4b Those who go out from the assemblies and solemn conclaves of the church should exercise great care in their ministration abroad, both to the branches where they may officiate and in their preaching the gospel to those outside, to avoid sowing seeds of distrust and suspicion either in public ministration or in private conversation. D&C 131:4c The church has been admonished heretofore in this respect; and the Spirit saith again, It is unbecoming to the character and calling of those who administer in the name of Jesus Christ, the Lord. D&C 131:5 In witness whereof, I, Joseph Smith, president and servant of the church, hereto set my hand this fourteenth day of April in the year of our Lord 1914. (Signed) Joseph Smith', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (132, 1, 'April 5, 1916-Independence, Missouri. The first revelation given to the church through Frederick Madison Smith, who had been approved by the 1915 General Conference to be President of the high priesthood and of the church. Appointments to the Bishopric-The hastening time requires cooperation and consecration The matter of selecting one to succeed Bishop E. L. Kelley in the office of Presiding Bishop has received by me careful and prayerful consideration. D&C 132:1 I am, therefore, now prepared to say that the voice of the Spirit to me is that Bishop E. L. Kelley should be released from the responsibilities of Presiding Bishop, though he may act as traveling bishop, counseling and advising on the law of temporalities in harmony with his successor and the Presidency. D&C 132:2 Let Benjamin R. McGuire be set apart and ordained Presiding Bishop of the church, and two of the brethren be set apart as counselors to him-one to be selected by him and supported by the conference, the other to be Bishop James F. Keir. D&C 132:3a I admonish the church, and particularly those of the priesthood, that the hastening time being upon us, there is great necessity for confidence in the men of the church chosen for positions of great responsibility, D&C 132:3b and all should consecrate of their talents, abilities, and substance for the prosecution of the great work intrusted to us. D&C 132:4 Everywhere the demand for great activity exists; and for the accomplishment of our work, the great essential is fraternal cooperation in service to man and devoted consecration to God and his work. Your servant, Frederick M. Smith Independence, Missouri April 5, 1916', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (133, 1, 'April 7, 1920-Independence, Missouri. Revelation to the church through Frederick M. Smith. Appointments to the Quorum of Twelve-Apostles are to apply themselves diligently to the missionary effort To the Church: Having given to the general missionary needs of the church and the condition of the Quorum of Twelve much thought and prayer, I am permitted to say to the church by way of instruction, through inspiration received: D&C 133:1 Let Francis M. Sheehy and Peter Andersen be released from the Quorum of Twelve; and to fill the vacancies created by these releases let Myron A. McConley and Thomas W. Williams be ordained apostles. D&C 133:2a Let the Quorum of Twelve be admonished that to discharge the responsibilities of the burden of the missionary work upon them, they should in humility before God and in sincerity of purpose apply themselves to this great task with unreserved devotion. The work in this line must be hastened. D&C 133:2b Let them not be unduly concerned with the work of the standing ministry, only as they shall be directed by the Presidency therein; and let contention cease concerning the prerogatives of the leading quorums. D&C 133:2c The work awaiting the efforts of the missionary forces is great, and there is no time for contentions. D&C 133:2d Let the apostles move out, as they have in the past been directed, in the task of taking to the peoples of the world the message of peace; and they shall find comfort and satisfaction in their labors. Frederick M. Smith President of the Church Independence, Missouri April 7, 1920', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (134, 1, 'October 2, 1922-Independence, Missouri. Revelation through Frederick M. Smith regarding the leading quorums of the church. Vacancies filled in the Presidency and Quorum of Twelve-Apostles are to labor in missionary work, not in local administration-Let contention cease To the Church: To the matter of filling the leading quorums of the church in which vacancies now exist, I have given prayerful and careful consideration and meditation; and the voice of inspiration to me is: D&C 134:1 Let Floyd M. McDowell be ordained counselor to the President as a member of the First Presidency to fill the vacancy now existing. D&C 134:2 Let Gomer T. Griffiths, Ulysses W. Greene, Cornelius A. Butterworth, and Robert C. Russell be released from further responsibility as apostles, to devote their activities, as their strength and opportunity might permit, to local work or as evangelical ministers as might be determined by subsequent procedure. D&C 134:3 To fill the vacancies in the Quorum of Twelve, let the following be ordained apostles: Clyde F. Ellis, John F. Garver, Daniel T. Williams, F. Henry Edwards, Edmund J. Gleazer, Roy S. Budd. D&C 134:4 Let James A. Gillen be ordained president of the Quorum of Twelve. D&C 134:5a The field is large and the time opportune. D&C 134:5b Let the missionary work be prosecuted with great vigor; and if the Twelve will devote themselves wholeheartedly to this work, the church will be greatly blessed through their ministration. D&C 134:6a And let the Quorum of Twelve be further admonished that upon them rests the onerous burden of the missionary work of the church; D&C 134:6b and be not concerned with local administrative work except in emergencies or as sent by the Presidency, leaving the care of the local work to those officers previously indicated in the law. D&C 134:7 Let contention cease. Frederick M. Smith Independence, Missouri October 2, 1922', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (135, 1, 'April 18, 1925-Kansas City, Missouri. Revelation through Frederick M. Smith addressing a conflict regarding administrative prerogatives and differing views between the First Presidency and the Presiding Bishopric. The Order of Bishops had requested that the members of the Presiding Bishopric be honorably released. Members of the Presiding Bishopric to be released-Albert Carmichael called to be Presiding Bishop-Need for unity-No power shall stay the hand of God To the Church: Before and since the decision of the conference to have a season of prayer for divine direction in the matter before the conference, I have presented to the Lord the needs of the people; and through the voice of inspiration I am directed to say to the church: D&C 135:1 It is wisdom that the brethren of the present Presiding Bishopric be released from further responsibility in that office and that Albert Carmichael be ordained to act in the office of Presiding Bishop for a time, he to choose from among the bishops two to act as counselors. D&C 135:2a It is well that the documents from the joint council of April, 1924, have been approved; and the church is admonished once again that the great task laid upon it cannot be accomplished if contention continues. D&C 135:2b The hastening time is here, and greater unity than ever before is necessary if the forces of opposition are to be met; D&C 135:2c and such unity will prevail if those holding the priesthood will remember their commission to preach the gospel and each officer will strive to discharge his own duty and magnify his calling. D&C 135:3a The promise has been given that no power shall stay the hand of God in the accomplishment of his purposes among his people; D&C 135:3b and as the church shall move forward in its great work, the fulfillment of prophecy may cause the Saints to tremble at the exhibition of divine power; yet they shall rejoice in the protection of his grace. D&C 135:4 The authorities of the church, whose duty it is to appoint men to missionary tasks, should remember the previously given instructions to send out by twos; and so far as practicable, let the missionaries be so sent. There is wisdom and safety in this. Your servant, Frederick M. Smith Kansas City, Missouri April 18, 1925', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (136, 1, 'April 14, 1932-Independence, Missouri. Revelation to the church given through Frederick M. Smith during a period of financial difficulty resulting from the Great Depression. Appointments to the Bishopric and Quorum of Twelve-Unity of understanding and endeavor is pleasing to the Lord-Contention is denounced To the Church: To the condition of the church and the personnel of the Quorum of Twelve and Presiding Bishopric I have in official capacity, as well as in personal meditation and prayer, given much thought and have earnestly sought divine wisdom and guidance. Believing that such wisdom and inspiration have been given me, I present the following as the word of the Lord to us now: D&C 136:1a Under conditions existing, it is well that Bishop Albert Carmichael should be released from further responsibility as Presiding Bishop, he being commended for the faithful devotion to the onerous tasks which have been his to perform. D&C 136:1b In his stead let Bishop L. F. P. Curry be chosen to give such time and energy to this office as opportunity and the conditions surrounding him will permit, working toward the time when he can give his full time and attention to the work of the office to which he is thus called. D&C 136:1c In the work of the office, Bishop G. Leslie DeLapp should be associated as counselor, and one other be named by Bishop Curry as wisdom and the voice of inspiration may indicate, the selection to be ratified by the conference. D&C 136:2 To fill a vacancy existing in the number of the Twelve, let George G. Lewis be set apart and ordained as an apostle, and take his place with that quorum, and enter with his brethren upon the active work of the apostolic quorum and as representatives of the church. D&C 136:3a The movements toward better understanding of ministerial responsibilities, duties, and goals and toward unity of endeavor in teaching, preaching, evangelizing, and the perfecting of the Saints are pleasing to the Lord. D&C 136:3b Contentions, bickerings, and strife are unseemly, hinder the work of the church, and should not find place among the Saints. D&C 136:3c Only in the peace of fraternity and the unity of those caught up in the spirit of Zionic redemption can the work of the Lord be accomplished. To this task let the church devote its energies. Frederick M. Smith President of the Church Independence, Missouri April 14, 1932', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (137, 1, 'April 7, 1938-Independence, Missouri. Revelation to the church through Frederick M. Smith. Vacancies filled in the Quorum of Twelve-Elbert A. Smith is called to be Presiding Patriarch-The ministry of evangelists is essential to the work-Church is admonished to be faithful To the Church: Since the creation of two vacancies in the Quorum of Twelve, I have been quite concerned about the condition of that quorum, as well as other bodies in the church; and, after due meditation and prayer for divine light, I am permitted to present the following for the consideration and action of the conference members: D&C 137:1 Let J. Frank Curtis of the Twelve, who has long and faithfully served in that quorum, be honorably released from further responsibility as an apostle and take place in the ranks of the order of evangelists. D&C 137:2 To fill the vacancies in the Quorum of Twelve, let the following named brethren be ordained and set apart as apostles: C. George Mesley, Arthur A. Oakman, and Charles R. Hield. D&C 137:3 It is wise that Frederick A. Smith, who has become aged in long years of faithful service to the church in various offices, be released from further responsibility as active president of the order of evangelists, though he may be given the honor of being president emeritus of that order. D&C 137:4a To maintain the working condition of the order of evangelists, let Elbert A. Smith be released from further responsibility as counselor to the President of the church, to take up the work of presiding over the order of evangelists. D&C 137:4b And let the church be admonished that the functioning and work of this order is of great importance in the work of perfecting the Saints and the appointing authorities be reminded that the members of the order, so far as possible, are to be relieved of administrative work and keep themselves in condition for better functioning as evangelists, whose task is to build up faith in the gospel, and the church, and its work. D&C 137:4c And let those whose duty it is to select from the members of the priesthood those for setting apart as evangelists be admonished that the work of this class of ministers requires vigor, deep faith, and unreserved consecration; and men should be selected accordingly. D&C 137:5 Until such time as the vacancy in the First Presidency shall be duly filled, let the work of the Presidency be carried on with the aid of such assistants as may be arranged without undue interference with other departments. D&C 137:6a Let the church be admonished that the times are portentous and demand faithful adherence to the faith and work of the church, that mankind may be blessed by and find peace in those religiously social reforms and relationships which have been divinely imposed as a great task of achievement. D&C 137:6b Remember, and keep the commandments; be alert to keep out of the church and from its members those forces which make for disunity; and in harmony and saintly accord be about the task of freeing Zion from her bondage. Frederick M. Smith President of the Church Independence, Missouri April 7, 1938', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (138, 1, 'April 10, 1940-Independence, Missouri. Following the release of Elbert A. Smith and the resignation of F. M. McDowell from the First Presidency, President Frederick M. Smith received inspired instruction in October, 1938, to select Israel A. Smith and L. F. P. Curry to serve as his counselors. The action was approved by the Quorum of Twelve at that time and confirmed by the 1940 General Conference. Appointments to the First Presidency-G. Leslie DeLapp is called to be Presiding Bishop-The task of establishing Zion requires peace and harmony To the Saints in General Conference Assembled: D&C 138:1a As a result of the conditions existing when the Joint Council of First Presidency, Quorum of the Twelve, and Presiding Bishopric met in October, 1938, Brother Floyd M. McDowell, second counselor, presented his resignation to me to take effect immediately. D&C 138:1b This left the President without counselors; and to meet the situation, acting under such inspirational impulsions as were given me at the moment, I presented the names of Brethren Israel A. Smith and Lemuel F. P. Curry to fill the vacancies in the First Presidency, these selections being unanimously approved by the Quorum of Twelve. D&C 138:1c I suggested, to the brethren named, the wisdom of at once entering upon their tasks in the Presidency. D&C 138:1d This was done; and there was thrown upon Brother Curry a double responsibility, for it was thought best for him to continue his work as Presiding Bishop until further instructions were given. D&C 138:1e Acting further under the impulsion referred to, I now present the names of Israel A. Smith and Lemuel F. P. Curry for ratification as counselors in the First Presidency, Brother Curry to be released from further responsibility as Presiding Bishop. D&C 138:2 To effect necessary reorganization of the Presiding Bishopric, let G. Leslie DeLapp be selected and ordained as Presiding Bishop, he being left free to nominate his counselors in due time. D&C 138:3a Let the church again be admonished that the task of establishing Zion presses heavily upon us. D&C 138:3b Barriers and hindrances to the achievement of this goal should be removed as speedily as possible and practicable. D&C 138:3c To lay securely the foundations for Zion and her buildings, the work should be accomplished in peace and harmony. Unity should prevail. D&C 138:3d To this end, all the Saints should work together in the rich fraternity which can and will prevail among them when they keep faithfully the commandments. D&C 138:3e Great blessings are in store for the church if it will in faith and saintly devotion go forward in its tasks. Frederick M. Smith President of the Church Independence, Missouri April 10, 1940', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (139, 1, 'April 9, 1946-Independence, Missouri. Following the death of Frederick M. Smith on March 20, 1946, Presiding Patriarch Elbert A. Smith and the Quorum of Twelve testified to the General Conference that President Smith had designated his brother Israel A. Smith to be his successor. The Conference approved the call. This is the first revelation given through Israel A. Smith to the church following his ordination as President of the high priesthood and the church of Jesus Christ on April 7, 1946. Appointments to the First Presidency and Quorum of Twelve To the Quorums and to the General Conference: Beloved Brethren: Realizing our urgent need to receive light and instruction in order that the quorums might be filled, I have wrestled in prayer to God in my weakness on behalf and in the interest of the church-sensing deeply that it has been but a few hours ago when the burden of the church was laid upon me, yet in confidence and faith that God will not fail the church when called upon. In the early hours of yesterday and today I was blessed by the Spirit in power and assurance such as I have never before experienced. The mind of the Lord was manifested to me; and in the order named, my brethren have been presented to me as follows; and accordingly I have written: D&C 139:1a It is my will, saith the Spirit, that my servants of the Quorum of Twelve, John F. Garver and F. Henry Edwards, be ordained and set apart to be counselors to my servant, the President of the church, and to be presidents in the Quorum of the First Presidency. D&C 139:1b They are my chosen vessels and are qualified by experience. Their apostleship is extended in Presidency; and if they will go forward in loving service, their ministry will be very effective. D&C 139:2a To fill one of the vacancies in the Quorum of Twelve Apostles, I have presented to my servant the name of D. Blair Jensen of the high priests quorum, who is called and chosen to this office and should be ordained and set apart as a special witness in the Quorum of Twelve. D&C 139:2b My heart has been made to rejoice, as I feared that through my weakness and inexperience, the work of the church might suffer loss. I present this word to you soon after its reception; and, as I write, it is confirmed again unto me. D&C 139:2c May God bless you in your deliberations; and if the quorums and the body shall have this message confirmed unto them, I shall rejoice; and I have faith that the church thereby will be blessed. Your servant in Christ, Israel A. Smith President of the Church Independence, Missouri April 9, 1946', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (140, 1, 'April 7, 1947-Independence, Missouri. Revelation given to the church through Israel A. Smith. Unity is commended-Vacancies are filled in the Quorum of Twelve-Zionic conditions depend on the spiritual condition of the people To the Quorums and Councils of the Church and to the General Conference: For some time I have given prayerful consideration to the church and its present needs, in harmony with the call for prayer; and I am directed to present the following as the will of the Lord: D&C 140:1a The unity among my people and in the councils of the church is commendable. D&C 140:1b If those of the priesthood will perform their responsibilities in good fellowship and sustain each other, they will be supported by the faith and prayers of the church, and the work will go forward with increasing power. D&C 140:2 To fill vacancies already existing, let Roscoe E. Davey and Maurice L. Draper, now serving as seventies, be ordained apostles and occupy with their brethren in the Quorum of Twelve. D&C 140:3 My servant John W. Rushton has served his generation and the church long and faithfully; and he is honorably released from further responsibility as a member of the Quorum of Twelve, continuing to minister in his priesthood as he can and may desire without specific assignment. His works are with me, and his reward is sure. D&C 140:4a W. Wallace Smith is called and should be ordained an apostle and take his place in the councils of the church. D&C 140:4b This call was made known before, but my servant withheld it from the body for reasons that he believed were sufficient. D&C 140:5a The church is admonished again that all movements toward Zion, and the gathering, and temporalities connected therewith are within my law; and all things should be done in order- D&C 140:5b the advice and counsel of the elders and of the Bishop and his council be sought and honored when received, as before enjoined, though of necessity their counsel when given is not intended to dictate or to deny any man his agency. D&C 140:5c The work of preparation and the perfection of my Saints go forward slowly, and Zionic conditions are no further away nor any closer than the spiritual condition of my people justifies; D&C 140:5d but my word shall not fail, neither will my promises; for the foundation of the Lord standeth sure. Respectfully submitted, Israel A. Smith Independence, Missouri April 7, 1947', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (141, 1, 'October 2, 1948-Independence, Missouri. Encouragement and direction given to the church by revelation through Israel A. Smith. Vacancies in the Quorum of Twelve are filled-The hastening time-The work of the Seventy-Be not weary of well-doing To the Quorums, Councils, and Orders of the Church, and the General Conference: Since the day set for a fast and especially since the loss by death of Apostle Lewis, I have been led to seek the divine mind respecting the needs of the body. Light and intelligence have been manifested as a result, and I am permitted to present the following by way of encouragement and direction: To the Church: D&C 141:1 My servant George G. Lewis has been taken for mine own purposes. He has been faithful, and his labors have been acceptable to me. D&C 141:2 My servant Myron A. McConley is honorably released from further duty as an apostle, and he should be ordained to the office of evangelist and labor as a member of that order. D&C 141:3 In order that the Council of Twelve may be filled and the work of that quorum be carried forward, it is my will that my servants Percy E. Farrow and Reed M. Holmes be ordained and set apart unto the apostolic office and appointed to mission responsibility. D&C 141:4a There are others of the leading councils who have likewise served faithfully, whose ministry in my wisdom is continued for a season, but who may be taken to myself, or because of age or infirmity released in mine own due time. D&C 141:4b There are those with the body of my priesthood who are called and who will be chosen to succeed them-if faithful; therefore, all are admonished to qualify themselves in spirit by ministry and by witnessing for Christ. D&C 141:5 The hastening time is upon us; the period until the next General Conference, as already provided, must be one of unusual preparation for my church as an organization, for my people, and especially for my priesthood-if there shall be those who will be qualified to assume and to carry the responsibilities of those who fall, or fail, or who are released. D&C 141:6a Let the seventies under appointment as far as practicable relieve my servants of the Quorum of Twelve from labor in outlying or undeveloped areas; and let the Twelve seek to perfect the work in regions closer to the Center, opening up the work in new places. D&C 141:6b In these labors, the standing ministers, and especially district and stake authorities, are called to assist. D&C 141:6c Many of the elders not under appointment have a desire and will labor in new places if requested and given responsibility. D&C 141:7a The unity and spirit of tolerance evidenced by my servants in the councils of the church are commended of me. D&C 141:7b Each should strive prayerfully for sustained and greater devotion to the work whereunto he is called. D&C 141:7c My servants should not become weary of well-doing. The adversary is quick to discourage and thus destroy their effectiveness. D&C 141:8a The church is admonished again that joint responsibility is laid on all. D&C 141:8b Properly and equally borne, this responsibility will insure success, the consummation will be glorious, and all will share in that glory. Israel A. Smith Servant of the Church Independence, Missouri October 2, 1948', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (142, 1, 'April 2, 1950-Independence, Missouri. Revelation to the church given through Israel A. Smith in response to several concerns, including a vacancy in the First Presidency. William Wallace Smith is called to the First Presidency-Vacancy is filled in the Quorum of Twelve-Elders are to study and prepare for endowment-It is yet day when all can work To the Elders and to the Church: We approach the General Conference with a vacancy in our official circle. The death of President Garver left the Quorum of the First Presidency incomplete. This and other conditions have given me grave concern for the church. I have earnestly sought divine guidance; and it is with gratitude that I am able to transmit to the church, through the appointed channels, the following as the will of the Lord. The voice of inspiration directs me to say: D&C 142:1a It is wisdom that the leading quorums should be filled. Therefore, to take the place of my servant John F. Garver, whose sacrifices and labor were acceptable to me, D&C 142:1b it is my will that William Wallace Smith be ordained and set apart to take his place as counselor to the President of the high priesthood and as a member of the Quorum of the First Presidency, to which office he is now called. D&C 142:2 To fill the vacancy thus created in the Quorum of Twelve, Donald O. Chesworth is called. He should be ordained to the office of an apostle, and be relieved of his present bishopric, and assume the duties of a special witness in that council. D&C 142:3 My servants of the Joint Council are commended for the spirit of moderation which they have shown in their deliberations. I have accordingly blessed their efforts, and the cause has been measurably enriched. D&C 142:4a The church as a whole is commended for the spiritual growth and the preparation of the priesthood during the conference period, and this necessary work should proceed. D&C 142:4b It will be profitable for my servants of the eldership to meet often for study, under the direction of those having responsibility to teach, at such times and places as may be practicable, in preparation for the greater endowment of spiritual power which has been promised and which awaits the time when they can receive it. D&C 142:5a The hopes of my people and the goals of my church-while not yet fully realized and at times and to many seemingly distant-are closer to realization than many recognize. D&C 142:5b It is yet day when all can work. The night will come when for many of my people opportunity to assist will have passed. Your servant, Israel A. Smith Independence, Missouri April 2, 1950', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (143, 1, 'April 7, 1954-Independence, Missouri. Revelation through Israel A. Smith to the church. Selection of men to the Quorums of Twelve and Seventy To the Councils, Quorums, and Orders of the Church, and to the General Conference: D&C 143:1a When I was in England in 1952, I was given the assurance that Donald V. Lents, a high priest, was called to be an apostle. D&C 143:1b Now that there is a vacancy in the Council of Twelve, and realizing the great need for apostolic ministry and direction, I have made it a subject of prayer; and I am directed to submit this name to you, the voice of inspiration to me being: D&C 143:2 My servant Donald V. Lents is called, and he is now chosen to the holy office of an apostle and should be ordained to that office as soon as practicable. Pending that time, he should be placed in charge of the English and European Missions. D&C 143:3a The voice of inspiration to me also is as follows: It is wisdom for the church to accept the direction of the Council of Presidents of Seventy and complete their organization. My servants of this council should not be overcareful in selecting elders, under the law, to occupy as seventies. D&C 143:3b The field of opportunity in new places is great in all areas, and there are many who earnestly desire to do missionary work who are called to be seventies; and when they are ordained to that office, the church should devise ways and means, as far as practicable, for them to be given missionary assignment. D&C 143:4 The growing desire for missionary work will be amply rewarded, and the church will be blessed even more than in the past. Israel A. Smith Servant of the Church Independence, Missouri April 7, 1954', 'coc', 'Unknown', NULL, NULL);
INSERT INTO doctrine_covenants_verses (section, verse, text, tradition, prophet_received, date_received, conference_date)
VALUES (144, 1, 'May 28, 1952-Independence, Missouri. Prior to leaving for ministry in Europe, President Israel A. Smith prepared the following document. After his death on June 14, 1958, this document was brought to the attention of general church officers. It was approved at the General Conference of October, 1958. William Wallace Smith is appointed to be Israel A. Smith''s successor as President of the church To the Church and to the Council of Twelve Apostles: D&C 144:1 As I am about to go overseas, and realize the usual hazards of travel, and being ever conscious of the uncertainties of life and the certainty of death, and in order that my demise, whether soon or longer postponed, may not cause confusion, I hereby declare that in the event of my death, whenever it shall occur, my brother, William Wallace Smith, should be selected to succeed me as President of the high priesthood of the church, this having been manifested to me by the Lord at the time he was chosen and set apart as an apostle and again when he was called to be a counselor and member of the Quorum of the First Presidency at the General Conference of 1950. D&C 144:2 I feel at liberty to make this appointment at this time because he has become better acquainted with the members since he was called in 1947 and has proved himself to the body. D&C 144:3 This action is taken by me pursuant to the authority vested in me by the terms of Section 43 of the book of Doctrine and Covenants, in connection with other references in the law, notably paragraph 8 of Section 127, all as interpreted by my father, the late President Joseph Smith, in The Saints'' Herald of March 12, 1912, and all of which I believe is in complete harmony with precedents established by the church in General Conferences of 1860, 1915, and 1946. (Signed) Israel A. Smith Witnessed this 28th day of May, 1952 F. Henry Edwards G. Leslie DeLapp', 'coc', 'Unknown', NULL, NULL);

COMMIT;

-- Summary
SELECT
  COUNT(*) as total_coc_verses,
  MIN(section) as first_section,
  MAX(section) as last_section
FROM doctrine_covenants_verses
WHERE tradition = 'coc';
